# ════════════════════════════════════════════════════════════════════
# Page: Channels
# ════════════════════════════════════════════════════════════════════
# Federation eligibility — channels matching both rules get pushed to
# registry.tgarr.me. Friend chats, small groups, and content-sparse channels
# stay private; only sizeable resource channels seed the central moat.
CONTRIB_MIN_MEMBERS = 500
CONTRIB_MIN_MEDIA = 100


# Heuristic NSFW keyword classifier. Multi-script — Telegram resource
# channels span many languages.
import re as _re_aud
NSFW_RX = _re_aud.compile(
    r"(porn|xxx|nsfw|adult|18\+|hentai|erotic|nude|naked|onlyfan|onlyfans|"
    r"sexy|sex\b|"
    r"\b色情|\b成人|\b18禁|\b裸\b|\b淫|"
    r"эротик|порно|секс|"
    r"اباحي|سكس)",
    _re_aud.IGNORECASE,
)

# CSAM hardcoded block — never displayable, never federated, regardless of
# any user opt-in. Conservative keyword set; reports any match to
# /var/log/tgarr-csam-flags.log for human + IWF/NCMEC review.
CSAM_RX = _re_aud.compile(
    r"\b(loli|lolicon|shota|shotacon|child\s*porn|kid\s*porn|"
    r"pre[\s_-]*teen|under[\s_-]*age|\bcp\d+|\bcp_)\b",
    _re_aud.IGNORECASE,
)


def classify_audience(title: str, username: str) -> str:
    """Returns 'blocked_csam' (hard ban), 'nsfw' (gated), or 'sfw'."""
    blob = (title or "") + " " + (username or "")
    if CSAM_RX.search(blob):
        # Hard block. NEVER show. NEVER federate. Logged for review.
        try:
            with open("/tmp/tgarr-csam-flags.log", "a") as f:
                f.write(f"{time.time()}\t{title!r}\t{username!r}\n")
        except Exception:
            pass
        return "blocked_csam"
    return "nsfw" if NSFW_RX.search(blob) else "sfw"


@app.post("/api/channel/subscribe")
async def api_channel_subscribe(username: str = Form(...)):
    """Subscribe to a public Telegram channel WITHOUT joining it.

    The crawler's subscription_poller resolves the username, validates it,
    and starts a get_chat_history backfill. The user's Telegram account stays
    small (no mass-join ban risk), and we can index thousands of public
    channels limited only by Telegram rate limits.
    """
    u = username.strip().lstrip("@")
    if not re.match(r"^[A-Za-z][A-Za-z0-9_]{4,31}$", u):
        return JSONResponse({"status": "error",
                            "message": "invalid telegram username format"}, 400)
    async with db_pool.acquire() as conn:
        # Insert with a placeholder negative chat_id; poller will replace it
        # with the real one after get_chat resolves the username.
        existing = await conn.fetchval(
            "SELECT id FROM channels WHERE username ILIKE $1", u)
        if existing:
            await conn.execute(
                """UPDATE channels SET subscribed=TRUE, unfollowed_at=NULL, purged_at=NULL,
                   last_polled_at=NULL, subscribe_error=NULL
                   WHERE id=$1""", existing)
            return {"status": "ok", "message": f"already known — re-queued @{u}",
                    "channel_id": existing}
        # Synthesize a placeholder tg_chat_id below the legal range to avoid
        # collision; poller fixes it on first scan.
        placeholder = -abs(hash(u)) // 1000 - 1_000_000_000_000
        new_id = await conn.fetchval(
            """INSERT INTO channels (tg_chat_id, username, title,
                                     subscribed, backfilled, handle_known)
               VALUES ($1, $2, $3, TRUE, FALSE, FALSE)
               ON CONFLICT (tg_chat_id) DO NOTHING
               RETURNING id""",
            placeholder, u, f"@{u} (resolving…)")
    return {"status": "queued", "message": f"@{u} queued for first scan",
            "channel_id": new_id}


@app.post("/api/channel/unsubscribe/{tg_chat_id}")
async def api_channel_unsubscribe(tg_chat_id: int):
    """Stop reading a public channel and let its index be cleared.
    Also for a channel that is not followed at all: tgarr joins some channels
    by itself, reads them and leaves again, and such a channel stayed in the
    list for good - not followed, not joined, with a "+ Follow" button and no
    way to take it off. Never a chat the account is in, never a private one."""
    async with db_pool.acquire() as conn:
        await conn.execute(
            """UPDATE channels SET subscribed = FALSE, unfollowed_at = COALESCE(unfollowed_at, NOW())
               WHERE tg_chat_id = $1 AND username IS NOT NULL AND local_root IS NULL
                 AND (subscribed = TRUE OR COALESCE(is_joined, FALSE) = FALSE)""", tg_chat_id)
    return {"status": "ok"}


@app.post("/api/channel/{tg_chat_id}/audience")
async def api_set_audience(tg_chat_id: int, value: str = Form(...)):
    if value not in ("sfw", "nsfw", "unknown"):
        return JSONResponse({"status": "error", "message": "value must be sfw/nsfw/unknown"},
                          status_code=400)
    async with db_pool.acquire() as conn:
        await conn.execute(
            "UPDATE channels SET audience=$1, audience_manual=TRUE WHERE tg_chat_id=$2",
            None if value == "unknown" else value, tg_chat_id)
    return {"status": "ok", "audience": value}


@app.get("/channels", response_class=HTMLResponse)
async def page_channels(q: Optional[str] = None, show: str = "all", sort: str = "films",
                        order: str = "", offset: int = 0, limit: int = 50,
                        min_members: Optional[int] = None, eligible: int = 0,
                        audience: str = ""):
    if not login.session_exists():
        return RedirectResponse("/login")
    if eligible:                       # old links
        show = "shared"
    nsfw_on = await _is_nsfw_enabled()
    async with db_pool.acquire() as conn:
        # Lazy classify (Python-side) — pulls untagged rows and tags them
        # before listing. Manual overrides untouched.
        untagged = await conn.fetch(
            """SELECT tg_chat_id, title, username FROM channels
               WHERE audience IS NULL AND audience_manual = FALSE
                 AND (title IS NOT NULL OR username IS NOT NULL)""")
        for u in untagged:
            await conn.execute(
                "UPDATE channels SET audience=$1 WHERE tg_chat_id=$2",
                classify_audience(u["title"], u["username"]), u["tg_chat_id"])
        # One pass over messages for every channel's numbers (the page used to
        # run three sub-queries per channel).
        rows = await conn.fetch(
            """WITH agg AS (
                 SELECT channel_id, count(*) AS msgs, count(file_name) AS media,
                        count(*) FILTER (WHERE media_type = 'video') AS videos,
                        count(*) FILTER (WHERE media_type = 'audio') AS songs,
                        count(*) FILTER (WHERE media_type = 'photo') AS photos,
                        count(*) FILTER (WHERE media_type = 'document') AS docs,
                        max(posted_at) AS last_post
                 FROM messages GROUP BY channel_id),
               rel AS (
                 SELECT m.channel_id, count(*) AS films FROM releases r
                 JOIN messages m ON m.id = r.primary_msg_id
                 WHERE r.category IN ('movie', 'tv') GROUP BY 1)
               SELECT c.tg_chat_id, c.username, c.title, c.backfilled, c.members_count,
                      c.audience, c.subscribed, c.is_joined, c.dead_at, c.subscribe_error,
                      c.purged_at, c.unfollowed_at, c.handle_known, c.web_preview,
                      COALESCE(a.msgs, 0) AS msgs, COALESCE(a.media, 0) AS media,
                      COALESCE(a.videos, 0) AS videos, COALESCE(a.songs, 0) AS songs,
                      COALESCE(a.photos, 0) AS photos, COALESCE(a.docs, 0) AS docs,
                      a.last_post, COALESCE(rel.films, 0) AS films
               FROM channels c
               LEFT JOIN agg a ON a.channel_id = c.id
               LEFT JOIN rel ON rel.channel_id = c.id
               WHERE COALESCE(c.audience, 'sfw') <> 'blocked_csam'""")
    rows = [r for r in rows if nsfw_on or (r["audience"] or "sfw") != "nsfw"]
    # Does this install clean a channel out of its index once nobody follows
    # it? (TGARR_INDEX_PURGE on the crawler; off unless switched on.) What
    # "Unfollow" means depends on it, and the page has to say which.
    async with db_pool.acquire() as conn:
        purge_on = (await conn.fetchval(
            "SELECT value FROM config WHERE key = 'index_purge'")) == "on"

    def _shared(r):
        return (r["members_count"] or 0) >= CONTRIB_MIN_MEMBERS and r["media"] >= CONTRIB_MIN_MEDIA
    # A channel the user unfollowed has left the list as far as they are
    # concerned, even while its index is still being cleared: it shows only
    # under "being cleared" (where it can be followed again in time).
    def _uf(r):
        return bool(r["unfollowed_at"]) and not r["subscribed"] and not r["is_joined"]
    kinds = {
        "all": lambda r: not _uf(r),
        "films": lambda r: r["films"] > 0 and not _uf(r),
        "joined": lambda r: r["is_joined"],
        "subscribed": lambda r: r["subscribed"] and not r["is_joined"],
        "shared": lambda r: _shared(r) and not _uf(r),
        "loose": lambda r: not r["is_joined"] and not r["subscribed"] and not r["dead_at"] and not _uf(r),
        "empty": lambda r: r["media"] == 0 and not _uf(r),
        "dead": lambda r: r["dead_at"] is not None and not _uf(r),
        "clearing": _uf,
    }
    if show not in kinds:
        show = "all"
    counts = {k: sum(1 for r in rows if f(r)) for k, f in kinds.items()}
    view = [r for r in rows if kinds[show](r)]
    if q:
        words = [w.lower() for w in q.split()]
        view = [r for r in view
                if all(w in ((r["title"] or "") + " " + (r["username"] or "")).lower() for w in words)]
    def _name(r):
        return (r["title"] or r["username"] or "~").lower()
    sorts = {
        "films": lambda r: (r["films"], r["media"]),
        "media": lambda r: (r["media"], r["films"]),
        "members": lambda r: r["members_count"],
        "recent": lambda r: r["last_post"],
        "name": _name,
    }
    if sort not in sorts:
        sort = "films"
    first_dir = {"name": "asc"}
    if order not in ("asc", "desc"):
        order = first_dir.get(sort, "desc")
    view = _ls_sort(view, sorts[sort], order, _name)
    page_size = max(10, min(limit, 200))
    page_offset = max(0, offset)
    page = view[page_offset:page_offset + page_size]

    def _cqs(**over):
        cur = {"q": q, "show": show if show != "all" else None,
               "sort": sort if sort != "films" else None,
               "order": order if order != first_dir.get(sort, "desc") else None,
               "limit": limit if limit != 50 else None}
        cur.update(over)
        bits = [f"{k}={_q(str(v))}" for k, v in cur.items() if v not in (None, "", 0)]
        return "?" + "&".join(bits) if bits else ""

    _tip = html.unescape              # _chip_link escapes its tooltip itself: hand it the plain word

    def _n(k):
        return f' <span style="opacity:.6">{counts[k]:,}</span>'
    chips = (
        _chip_link(_t("all") + _n("all"), "/channels" + _cqs(show=None, offset=None), show == "all")
        + _chip_link("🎬 " + _t("with films") + _n("films"), "/channels" + _cqs(show="films", offset=None),
                     show == "films", _tip(_t("channels that carry recognised films or episodes")))
        + _chip_link(_t("joined") + _n("joined"), "/channels" + _cqs(show="joined", offset=None),
                     show == "joined", _tip(_t("channels your Telegram account is a member of")))
        + _chip_link(_t("followed") + _n("subscribed"), "/channels" + _cqs(show="subscribed", offset=None),
                     show == "subscribed", _tip(_t("public channels tgarr reads without joining")))
        + _chip_link(_t("shared") + _n("shared"), "/channels" + _cqs(show="shared", offset=None),
                     show == "shared",
                     _tip(_t("{members}+ members and {files}+ files: listed on tgarr.me for other people to find. Private chats and small groups never are.", members=CONTRIB_MIN_MEMBERS, files=CONTRIB_MIN_MEDIA)))
        + (_chip_link(_t("not followed") + _n("loose"), "/channels" + _cqs(show="loose", offset=None),
                      show == "loose",
                      _tip(_t("channels this install knows but no longer reads: their files are being cleared from this index")
                           if purge_on else _t("channels this install knows but no longer reads")))
           if counts["loose"] else "")
        + _chip_link(_t("no files") + _n("empty"), "/channels" + _cqs(show="empty", offset=None), show == "empty")
        + (_chip_link(_t("gone") + _n("dead"), "/channels" + _cqs(show="dead", offset=None),
                      show == "dead", _tip(_t("channels Telegram no longer serves"))) if counts["dead"] else "")
        + (_chip_link(_t("being cleared") + _n("clearing"), "/channels" + _cqs(show="clearing", offset=None),
                      show == "clearing",
                      _tip(_t("channels you unfollowed: their index is being cleared and they then disappear. Follow one again here to keep it."))) if counts["clearing"] else "")
        # on a phone there is no room for the column header: the same sorts as chips
        + '<span class="sort-chips"><span class="sep"></span><span class="lbl">' + _t("Sort:") + '</span>'
        + _chip_link(_t("films"), "/channels" + _cqs(sort=None, order=None, offset=None), sort == "films")
        + _chip_link(_t("files"), "/channels" + _cqs(sort="media", order=None, offset=None), sort == "media")
        + _chip_link(_t("members"), "/channels" + _cqs(sort="members", order=None, offset=None), sort == "members")
        + _chip_link(_t("latest post"), "/channels" + _cqs(sort="recent", order=None, offset=None), sort == "recent")
        + _chip_link(_t("name"), "/channels" + _cqs(sort="name", order=None, offset=None), sort == "name")
        + '</span>')
    head = _ls_head(
        (("name", "Channel", "ls-main", "asc"), ("films", "Films", "ls-num", "desc"),
         ("media", "Files", "ls-num", "desc"), ("members", "Members", "ls-num", "desc"),
         ("recent", "Latest post", "ls-num lp", "desc"), (None, "", "ls-act", "")),
        sort, order, lambda k, d: "/channels" + _cqs(sort=k if k != "films" else None,
                                                     order=d if d != first_dir.get(k, "desc") else None,
                                                     offset=None))
    search = (
        '<form method="GET" action="/channels" style="display:flex;gap:8px;margin:0 0 12px">'
        + "".join(f'<input type="hidden" name="{k}" value="{html.escape(str(v), quote=True)}"/>'
                  for k, v in (("show", show if show != "all" else None),
                               ("sort", sort if sort != "films" else None),
                               ("order", order if order != first_dir.get(sort, "desc") else None)) if v)
        + f'<input type="text" name="q" value="{html.escape(q or "", quote=True)}" '
          f'placeholder="{_t("find a channel by name or @username…")}" style="flex:1;max-width:420px"/>'
          f'<button class="btn" type="submit">{_t("Search")}</button>'
        + (f'<a class="btn ghost" href="/channels{_cqs(q=None, offset=None)}">{_t("clear")}</a>' if q else '')
        + '</form>')

    def _row(r):
        title = r["title"] or (("@" + r["username"]) if r["username"] else html.unescape(_t("(untitled)")))
        handle = (f'<a href="https://t.me/{html.escape(r["username"])}" target="_blank" rel="noopener" '
                  f'title="{_t("open in Telegram")}">@{html.escape(r["username"])}</a>'
                  if r["username"] else f'<span>{_t("private chat")}</span>')
        tags = []
        if r["dead_at"]:
            tags.append(f'<span class="tag bad" title="{_t("Telegram no longer serves this channel")}">{_t("gone")}</span>')
        elif r["is_joined"]:
            tags.append(f'<span class="tag ok" title="{_t("your account is a member")}">{_t("joined")}</span>')
        elif r["subscribed"] and not r["handle_known"]:
            tags.append(f'<span class="tag acc" title="{_t("read from tgarr.me and Telegram’s public web page; your account is not used until you open one of its files")}">'
                        + (_t("followed · web") if r["web_preview"] else _t("followed · listed")) + '</span>')
        elif r["subscribed"]:
            tags.append(f'<span class="tag acc" title="{_t("read without joining")}">{_t("followed")}</span>')
        elif r["unfollowed_at"]:
            tags.append(f'<span class="tag warn" title="{_t("you unfollowed it: its films and files are being cleared from this index and it will leave this list. Follow it again to keep it.")}">{_t("unfollowed · being cleared")}</span>')
        elif r["purged_at"] and not purge_on:
            tags.append(f'<span class="tag" title="{_t("unfollowed and cleared; only files you saved or marked as favourite are still here")}">{_t("not followed · cleared")}</span>')
        elif purge_on and r["purged_at"]:
            tags.append(f'<span class="tag" title="{_t("not followed any more; its files have been cleared from this index. tgarr.me still lists it: follow it again to get them back.")}">{_t("not followed · cleared")}</span>')
        elif purge_on:
            tags.append(f'<span class="tag warn" title="{_t("not followed any more: its films and files are being cleared from this index (tgarr.me keeps the record). Follow it again to keep them.")}">{_t("not followed · being cleared")}</span>')
        else:
            tags.append(f'<span class="tag" title="{_t("not read any more; what was indexed stays")}">{_t("not followed")}</span>')
        if _shared(r):
            tags.append(f'<span class="tag" title="{_t("listed on tgarr.me")}">{_t("shared")}</span>')
        if (r["audience"] or "sfw") == "nsfw":
            tags.append('<span class="tag warn">18+</span>')
        if not r["backfilled"] and not r["dead_at"]:
            tags.append(f'<span class="tag warn" title="{_t("still reading its history")}">{_t("reading…")}</span>')
        if r["subscribe_error"] and not r["dead_at"]:
            tags.append(f'<span class="tag bad" title="{html.escape(r["subscribe_error"], quote=True)}">'
                        f'{_t("cannot read")}</span>')
        has = []
        for n, ico, word, href in (
                (r["films"], "🎬", "films", None),
                (r["videos"], "▶", "videos", None),
                (r["songs"], "🎵", "songs", None),
                (r["docs"], "📄", "files", None),
                (r["photos"], "🖼", "photos",
                 f'/gallery?channel={_q(r["username"])}' if r["username"] else None)):
            if n:
                txt = f'{ico} {_n_things(n, word)}'
                has.append(f'<a href="{href}">{txt}</a>' if href else f'<span>{txt}</span>')
        act = ""
        _ids = (f'data-id="{r["tg_chat_id"]}" '
                f'data-uname="{html.escape(r["username"] or "", quote=True)}"')
        if r["subscribed"] and not r["is_joined"]:
            act = (f'<button class="abtn" {_ids} onclick="tgUnfollow(this)" '
                   f'title="{_t("stop reading this channel")}">{_t("Unfollow")}</button>')
        elif not r["is_joined"] and not r["dead_at"] and r["username"]:
            act = (f'<button class="abtn pri" {_ids} onclick="tgFollow(this)" '
                   f'title="{_t("read this public channel again, without joining it")}">+ {_t("Follow")}</button>')
            if not r["unfollowed_at"]:
                # not followed, not joined, and nobody ever unfollowed it: it can be taken off the list
                act += (f' <button class="abtn" {_ids} onclick="tgRemove(this)" '
                        f'title="{_t("take this channel and its index off this tgarr")}">{_t("Remove")}</button>')
        return (
            f'<div class="ls-row">{_avatar(title)}'
            f'<div class="ls-main"><div class="ls-title">{html.escape(title)} '
            f'{" ".join(tags)}</div>'
            f'<div class="ls-sub">{handle}{"".join(has) or "<span>" + _t("no files indexed") + "</span>"}</div></div>'
            f'<div class="ls-num"><b>{_fmt_count(r["films"]) if r["films"] else "–"}</b></div>'
            f'<div class="ls-num"><b>{_fmt_count(r["media"]) if r["media"] else "–"}</b></div>'
            f'<div class="ls-num"><b>{_fmt_count(r["members_count"])}</b></div>'
            f'<div class="ls-num lp"><b style="font-size:13px;font-weight:500">'
            f'{_ago(r["last_post"]) or "–"}</b></div>'
            f'<div class="ls-act">{act}</div></div>')

    if not page:
        listing = ('<div class="empty-state"><div class="icon">📡</div><div>'
                   + (_t("No channel matches.") if (q or show != "all") else
                      _t("No channels yet. Join channels in Telegram, or follow some from Discover."))
                   + '</div></div>')
    else:
        listing = (f'<div class="ls">{head}{"".join(_row(r) for r in page)}</div>'
                   + _page_nav("/channels", _cqs, page_offset, page_size, len(page), len(view)))
    body = (
        f'{_LIST_CSS}<style>.ls-num{{width:76px}}.ls-num.lp{{width:104px}}</style>'
        f'<h2 class="section">{_t("Channels")} <span class="count">'
        + (_t("{n} of {total}", n=f"{len(view):,}", total=f"{len(rows):,}") if len(view) != len(rows) else f'{len(view):,}') + '</span>'
        '<span class="extra" style="color:var(--muted);font-size:12px;font-weight:400;text-transform:none;'
        'letter-spacing:0;margin-left:10px"><a href="/discover">' + _t("find more on Discover →") + '</a></span></h2>'
        f'{search}<div class="bar-tools">{chips}</div>{listing}'
        # The button changes where it is. Reloading the page for one click
        # threw the reader back to the top of a long list every time.
        '<script>var tgUnfollowAsk=' + _js_str(
            html.unescape(_t("Stop reading this channel and take it off this list?")) + "\n\n"
            + html.unescape(_t("Its films and files are cleared from this index within a few hours. Files you saved to this machine and your favourites are kept. You can find the channel again on Discover.")))
        + _fill(r""";
function tgChGone(b, note) {
  var row = b.closest(".ls-row");
  b.disabled = true; b.textContent = note;
  if (row) { row.style.transition = "opacity .5s"; row.style.opacity = "0.35";
             setTimeout(function () { row.remove(); }, 900); }
  // the numbers in the heading and on the chips are from when the page was made: once the
  // last of a run of clicks has settled, read the page again so that they are right
  clearTimeout(window.tgChAgain);
  window.tgChAgain = setTimeout(function () { location.reload(); }, 1800);
}
function tgChSet(b, following) {
  // unfollowed: it has left the list. Followed again from "being cleared": it has left that view.
  if (!following) { tgChGone(b, "[[@js:Removed]]"); return; }
  if (location.search.indexOf("show=clearing") >= 0) { tgChGone(b, "[[@js:Following]]"); return; }
  b.disabled = false;
  if (following) {
    b.className = "abtn"; b.textContent = "[[@js:Unfollow]]"; b.title = "[[@js:stop reading this channel]]";
    b.onclick = function () { tgUnfollow(b); };
  } else if (b.dataset.uname) {
    b.className = "abtn pri"; b.textContent = "+ [[@js:Follow]]";
    b.title = "[[@js:read this public channel again, without joining it]]";
    b.onclick = function () { tgFollow(b); };
  } else { b.remove(); }
}
function tgChFail(b, label, why) {
  b.disabled = false; b.textContent = "[[@js:Failed - retry]]"; b.title = why || "[[@js:the request did not go through]]";
  setTimeout(function () { if (b.textContent === "[[@js:Failed - retry]]") b.textContent = label; }, 4000);
}
function tgUnfollow(b) {
  if (!confirm(tgUnfollowAsk)) return;
  b.disabled = true; b.textContent = "…";
  fetch("/api/channel/unsubscribe/" + b.dataset.id, {method: "POST"})
    .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); tgChSet(b, false); })
    .catch(function (e) { tgChFail(b, "[[@js:Unfollow]]", e.message); });
}
function tgRemove(b) {
  if (!confirm("[[@js:Remove this channel from tgarr?]]\n\n"
               + "[[@js:Its films and files leave the index within a few hours. Files you saved and favourites stay. It can be followed again from Discover.]]")) return;
  b.disabled = true; b.textContent = "…";
  fetch("/api/channel/unsubscribe/" + b.dataset.id, {method: "POST"})
    .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); tgChGone(b, "[[@js:Removed]]"); })
    .catch(function (e) { tgChFail(b, "[[@js:Remove]]", e.message); });
}
function tgFollow(b) {
  b.disabled = true; b.textContent = "…";
  fetch("/api/channel/subscribe", {method: "POST",
        headers: {"Content-Type": "application/x-www-form-urlencoded"},
        body: "username=" + encodeURIComponent(b.dataset.uname)})
    .then(function (r) { return r.json().then(function (j) {
      if (!r.ok || j.status === "error") throw new Error(j.message || ("HTTP " + r.status));
      tgChSet(b, true); }); })
    .catch(function (e) { tgChFail(b, "+ [[@js:Follow]]", e.message); });
}
</script>"""))
    return HTMLResponse(_layout("Channels", "/channels", body))


# ════════════════════════════════════════════════════════════════════
# Page: Discover (registry-pulled channels awaiting subscription)
# ════════════════════════════════════════════════════════════════════
def _profile_pills(r) -> str:
    """Small pills saying what a discovered channel carries."""
    out = []
    for col, label in (("release_files", "🎬 {n} releases"),
                       ("book_files", "📚 {n} books"),
                       ("audio_files", "🎵 {n} tracks")):
        n = r[col] or 0
        if n > 0:
            out.append(f'<span class="pill accent">{label.format(n=f"{n:,}")}</span>')
    return "".join(out)


@app.get("/discover", response_class=HTMLResponse)
async def page_discover(audience: str = "sfw", kind: str = "", q: Optional[str] = None,
                        sort: str = "best", order: str = "", mine: int = 0, offset: int = 0,
                        limit: int = 50):
    async with db_pool.acquire() as conn:
        n_channels = await conn.fetchval("SELECT count(*) FROM channels")
        # (no account and nothing indexed: Discover is exactly where such an install starts)
        # Telegram sometimes returns a differently-cased username
        # (eBookRoom vs ebookroom): match case-insensitively.
        known = {r["username"].lower(): (r["subscribed"] or r["is_joined"])
                 for r in await conn.fetch(
                     "SELECT username, subscribed, is_joined FROM channels "
                     "WHERE username IS NOT NULL")}
        nsfw_on = await _is_nsfw_enabled()
        if audience == "nsfw" and not nsfw_on:
            audience = "sfw"
        where = ["dismissed = FALSE"]
        if audience in ("sfw", "nsfw"):
            where.append(f"audience = '{audience}'")
        kind = kind if kind in ("video", "books", "music") else ""
        kind_col = {"video": "release_files", "books": "book_files",
                    "music": "audio_files"}.get(kind)
        if kind_col:
            where.append(f"COALESCE({kind_col}, 0) > 0")
        rows = await conn.fetch(f"""
            SELECT username, title, members_count, media_count, audience,
                   language, category, distinct_contributors, verified,
                   last_pulled_at, release_files, video_files, book_files, audio_files,
                   last_file_at
            FROM discovered
            WHERE {' AND '.join(where)}""")
        total = await conn.fetchval("SELECT count(*) FROM discovered WHERE dismissed = FALSE")
        last_pull = await conn.fetchval("SELECT max(last_pulled_at) FROM discovered")

    have = [r for r in rows if known.get(r["username"].lower())]
    view = rows if mine else [r for r in rows if not known.get(r["username"].lower())]
    if q:
        words = [w.lower() for w in q.split()]
        view = [r for r in view
                if all(w in ((r["title"] or "") + " " + r["username"]).lower() for w in words)]
    lead = kind_col or "release_files"
    def _dname(r):
        return (r["title"] or r["username"]).lower()
    sorts = {
        # what the channel carries first - the reason most people install
        # tgarr - then how many installs vouch for it
        "best": lambda r: (r[lead] or 0, int(bool(r["verified"])),
                           r["distinct_contributors"] or 0, r["members_count"] or 0),
        "lead": lambda r: r[lead] or None,
        "seen": lambda r: (r["distinct_contributors"] or 0, r[lead] or 0),
        "members": lambda r: r["members_count"],
        "files": lambda r: r["media_count"] or None,
        "recent": lambda r: r["last_file_at"],
        "name": _dname,
    }
    if sort not in sorts:
        sort = "best"
    dfirst = {"name": "asc"}
    if order not in ("asc", "desc"):
        order = dfirst.get(sort, "desc")
    view = _ls_sort(view, sorts[sort], order, _dname)
    page_size = max(10, min(limit, 200))
    page_offset = max(0, offset)
    page = view[page_offset:page_offset + page_size]

    def _dq(**over):
        cur = {"kind": kind or None, "audience": audience if audience != "sfw" else None,
               "q": q, "sort": sort if sort != "best" else None,
               "order": order if order != dfirst.get(sort, "desc") else None,
               "mine": 1 if mine else None,
               "limit": limit if limit != 50 else None}
        cur.update(over)
        bits = [f"{k}={_q(str(v))}" for k, v in cur.items() if v not in (None, "", 0)]
        return "?" + "&".join(bits) if bits else ""

    chips = (
        _chip_link(_t("All"), "/discover" + _dq(kind=None, offset=None), not kind)
        + _chip_link("🎬 " + _t("Movies & TV"), "/discover" + _dq(kind="video", offset=None), kind == "video")
        + _chip_link("📚 " + _t("Books"), "/discover" + _dq(kind="books", offset=None), kind == "books")
        + _chip_link("🎵 " + _t("Music"), "/discover" + _dq(kind="music", offset=None), kind == "music")
        + ('<span class="sep"></span>'
           + _chip_link(_t("SFW"), "/discover" + _dq(audience=None, offset=None), audience == "sfw")
           + _chip_link("18+", "/discover" + _dq(audience="nsfw", offset=None), audience == "nsfw")
           if nsfw_on else '')
        + '<span class="sep"></span>'
        + _chip_link(_t("best match"), "/discover" + _dq(sort=None, order=None, offset=None), sort == "best",
                     html.unescape(_t("most of what you are looking at, then how many installs vouch for it")))
        + '<span class="sort-chips"><span class="lbl">' + _t("Sort:") + '</span>'
        + _chip_link(_t("most seen"), "/discover" + _dq(sort="seen", order=None, offset=None), sort == "seen",
                     html.unescape(_t("indexed by the most tgarr installs")))
        + _chip_link(_t("members"), "/discover" + _dq(sort="members", order=None, offset=None), sort == "members")
        + _chip_link(_t("files"), "/discover" + _dq(sort="files", order=None, offset=None), sort == "files")
        + _chip_link(_t("latest file"), "/discover" + _dq(sort="recent", order=None, offset=None), sort == "recent")
        + '</span>'
        + '<span class="sep"></span>'
        + _chip_link(_t("include the {n} I already have", n=f"{len(have):,}"), "/discover" + _dq(mine=None if mine else 1, offset=None),
                     bool(mine)))
    search = (
        '<form method="GET" action="/discover" style="display:flex;flex-wrap:wrap;gap:8px;margin:0 0 12px;align-items:center">'
        + "".join(f'<input type="hidden" name="{k}" value="{html.escape(str(v), quote=True)}"/>'
                  for k, v in (("kind", kind), ("audience", audience if audience != "sfw" else None),
                               ("sort", sort if sort != "best" else None),
                               ("order", order if order != dfirst.get(sort, "desc") else None),
                               ("mine", 1 if mine else None)) if v)
        + f'<input type="text" name="q" value="{html.escape(q or "", quote=True)}" '
          f'placeholder="{_t("find a channel by name or @username…")}" style="flex:1;min-width:150px;max-width:420px"/>'
          f'<button class="btn" type="submit">{_t("Search")}</button>'
        + (f'<a class="btn ghost" href="/discover{_dq(q=None, offset=None)}">{_t("clear")}</a>' if q else '')
        + '<span style="flex:1"></span>'
          '<span id="tgPullToast" style="font-size:13px;color:var(--muted);display:none"></span>'
        + ('<button type="button" class="abtn" id="tgPullBtn" onclick="tgRegistryPull(this)" '
           f'title="{_t("ask tgarr.me for its current list now")}">↻ {_t("Refresh list")}</button>' if _signed_in() else '')
        + '</form>')

    _in = _signed_in()

    def _card(r):
        u = r["username"]
        mine_ = known.get(u.lower())
        btn = (f'<button class="abtn" disabled>✓ {_t("Following")}</button>' if mine_ else
               f'<button class="abtn pri" data-uname="{html.escape(u, quote=True)}" '
               f'onclick="tgDiscoverSubscribe(this)" '
               + (f'title="{_t("tgarr reads this public channel without your account joining it")}">+ {_t("Follow")}</button>' if _in else
                  f'title="{_t("tgarr lists what this public channel holds without an account; playing a file needs one")}">+ {_t("Follow")}</button>'))
        title = r["title"] or ("@" + u)
        has = []
        for n, ico, word in ((r["release_files"], "🎬", "films"), (r["book_files"], "📚", "books"),
                             (r["audio_files"], "🎵", "songs")):
            if n:
                has.append(f'<span style="color:var(--fg)">{ico} {_n_things(n, word)}</span>')
        if r["media_count"]:
            has.append(f'<span>{_n_things(r["media_count"], "files")}</span>')
        seen = r["distinct_contributors"] or 1
        return (
            f'<div class="ls-row">{_avatar(title)}'
            f'<div class="ls-main"><div class="ls-title">{html.escape(title)} '
            + (f'<span class="tag ok" title="{_t("tgarr.me checked that this channel exists and is public")}">✓ {_t("verified")}</span> '
               if r["verified"] else '')
            + ('<span class="tag warn">18+</span>' if r["audience"] == "nsfw" else '')
            + f'</div><div class="ls-sub"><a href="https://t.me/{html.escape(u)}" target="_blank" rel="noopener" '
            f'title="{_t("open in Telegram")}">@{html.escape(u)}</a>{"".join(has)}</div></div>'
            f'<div class="ls-num"><b>{_fmt_count(r[lead]) if r[lead] else "–"}</b></div>'
            f'<div class="ls-num"><b>{_fmt_count(r["media_count"]) if r["media_count"] else "–"}</b></div>'
            f'<div class="ls-num"><b>{_fmt_count(r["members_count"])}</b></div>'
            f'<div class="ls-num" title="{_t("tgarr installs that index this channel")}"><b>{seen:,}</b></div>'
            f'<div class="ls-num lp" title="{_t("when the newest file that tgarr installs have reported for this channel was posted")}">'
            f'<b style="font-size:13px;font-weight:500">'
            f'{_ago(r["last_file_at"]) or "–"}</b></div>'
            f'<div class="ls-act">{btn}</div></div>')

    if not rows and not total:
        listing = ('<div class="empty-state"><div class="icon">🔭</div>'
                   f'<div>{_t("The list from tgarr.me has not arrived yet.")}</div>'
                   f'<div style="margin-top:8px;font-size:13px">{_t("It is fetched every 12 hours; “Refresh list” asks for it now.")}</div></div>')
    elif not page:
        listing = ('<div class="empty-state"><div class="icon">🔭</div><div>'
                   + (_t("No channel matches.") if (q or kind) else
                      _t("This part of the list has not arrived yet.") if not rows else
                      _t("You already follow everything on the list.")) + '</div>'
                   + (f'<div style="margin-top:8px;font-size:13px">{_t("“Refresh list” asks tgarr.me for it now.")}</div>'
                      if not rows and not (q or kind) else '') + '</div>')
    else:
        dhead = _ls_head(
            (("name", "Channel", "ls-main", "asc"),
             ("lead", {"book_files": "Books", "audio_files": "Songs"}.get(lead, "Films"), "ls-num", "desc"),
             ("files", "Files", "ls-num", "desc"), ("members", "Members", "ls-num", "desc"),
             ("seen", "Installs", "ls-num", "desc"), ("recent", "Latest file", "ls-num lp", "desc"),
             (None, "", "ls-act", "")),
            sort, order, lambda k, d: "/discover" + _dq(sort=k, order=d if d != dfirst.get(k, "desc") else None,
                                                        offset=None))
        listing = (f'<div class="ls">{dhead}{"".join(_card(r) for r in page)}</div>'
                   + _page_nav("/discover", _dq, page_offset, page_size, len(page), len(view)))

    body = (
        f'{_LIST_CSS}<style>.ls-num{{width:76px}}.ls-num.lp{{width:104px}}</style>'
        f'<h2 class="section">{_t("Discover")} <span class="count">{len(view):,}</span>'
        '<span class="extra" style="color:var(--muted);font-size:12px;font-weight:400;text-transform:none;'
        f'letter-spacing:0;margin-left:10px">{_t("public channels other tgarr installs index")} · '
        + _t("{n} on tgarr.me", n=f"{total or 0:,}")
        + (' · ' + _t("list from {when}", when=html.unescape(_ago(last_pull))) if last_pull else '') + '</span></h2>'
        f'{search}<div class="bar-tools">{chips}</div>{listing}'
        + _fill(
        '<script>'
        '(() => {'
        '  window.tgRegistryPull = async function(btn) {'
        '    const toast = document.getElementById("tgPullToast");'
        '    btn.disabled = true; btn.textContent = "[[@js:Refreshing…]]";'
        '    toast.style.display = "inline";'
        '    toast.textContent = "[[@js:asking tgarr.me (up to a minute)…]]";'
        '    toast.style.color = "var(--muted)";'
        '    try {'
        '      const r = await fetch("/api/registry/pull-now", {method:"POST"});'
        '      const j = await r.json();'
        '      if (j.status === "ok") {'
        '        toast.textContent = "✓ " + "[[@js:channels updated: %1]]".replace("%1", j.affected);'
        '        toast.style.color = "var(--ok)";'
        '        if (j.affected > 0) setTimeout(() => location.reload(), 1200);'
        '      } else if (j.status === "queued") {'
        '        toast.textContent = "[[@js:queued — it will run shortly]]";'
        '        toast.style.color = "var(--warn)";'
        '      } else {'
        '        toast.textContent = "✗ " + (j.message || "[[@js:error]]");'
        '        toast.style.color = "var(--err)";'
        '      }'
        '    } catch (e) {'
        '      toast.textContent = "✗ [[@js:network error]]";'
        '      toast.style.color = "var(--err)";'
        '    } finally {'
        '      btn.disabled = false; btn.textContent = "↻ [[@js:Refresh list]]";'
        '    }'
        '  };'
        '  window.tgDiscoverSubscribe = async function(btn) {'
        '    const u = btn.dataset.uname;'
        '    btn.disabled = true; btn.textContent = "…";'
        '    try {'
        '      const r = await fetch("/api/channel/subscribe", {method:"POST", '
        '          headers:{"Content-Type":"application/x-www-form-urlencoded"}, '
        '          body: "username=" + encodeURIComponent(u)});'
        '      const j = await r.json();'
        '      if (j.status === "queued" || j.status === "ok") {'
        '        btn.textContent = "✓ [[@js:Following]]"; btn.classList.remove("pri");'
        '      } else { btn.disabled = false; btn.textContent = "✗ " + (j.message || "[[@js:error]]"); }'
        '    } catch(e) { btn.disabled = false; btn.textContent = "✗ [[@js:network error]]"; }'
        '  };'
        '})();'
        '</script>')
    )
    return HTMLResponse(_layout("Discover", "/discover", body))


@app.post("/api/registry/pull-now")
async def api_registry_pull_now():
    """Force the next registry_puller tick to fire immediately and block until
    it consumes the sentinel (up to ~70s — crawler polls config every 60s).
    Returns JSON with how many discovered rows changed so the UI can show a
    real result toast instead of silent redirect.
    """
    import asyncio
    async with db_pool.acquire() as conn:
        before_max = await conn.fetchval(
            "SELECT MAX(last_pulled_at) FROM discovered")
        await conn.execute(
            """INSERT INTO config (key, value) VALUES ('registry_pull_force', $1)
               ON CONFLICT (key) DO UPDATE SET value=$1, updated_at=NOW()""",
            time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()))

    # Poll for sentinel deletion (crawler consumed it = pull completed).
    for _ in range(140):  # 140 * 0.5s = 70s
        await asyncio.sleep(0.5)
        async with db_pool.acquire() as conn:
            sentinel = await conn.fetchval(
                "SELECT value FROM config WHERE key='registry_pull_force'")
        if sentinel is None:
            async with db_pool.acquire() as conn:
                if before_max:
                    affected = await conn.fetchval(
                        "SELECT COUNT(*) FROM discovered WHERE last_pulled_at > $1",
                        before_max)
                else:
                    affected = await conn.fetchval(
                        "SELECT COUNT(*) FROM discovered WHERE last_pulled_at IS NOT NULL")
            return JSONResponse({"status": "ok", "affected": int(affected or 0)})

    return JSONResponse(
        {"status": "queued",
         "message": "crawler didn\'t pick up sentinel within 70s; pull will run in background"},
        status_code=202)


# ════════════════════════════════════════════════════════════════════
# Page: Gallery (Telegram-shared photos)
# ════════════════════════════════════════════════════════════════════
# ════════════════════════════════════════════════════════════════════
# Usenet - a second source, for people who have a Usenet account
#
# Off until an account is entered in Settings and the server answers. Then:
#   * a slow scanner reads newsgroup headers and keeps one small card per
#     named video / audio / e-book / photo release (usenet.py);
#   * /newznab/usenet/api offers those cards to Sonarr and Radarr;
#   * a grab is answered with the release's NZB, built at that moment by
#     reading its stretch of headers again. tgarr does not download from
#     Usenet: the *arr hands the NZB to its own downloader (SABnzbd, NZBGet).
# In the *arr this is a second indexer entry, because an indexer is tied to
# one download client: "tgarr" goes to tgarr itself (Telegram), "tgarr
# Usenet" to the Usenet downloader.
# ════════════════════════════════════════════════════════════════════
_USENET = {"at": 0.0, "cfg": {}, "ok": None, "msg": "not tried yet", "checked": 0.0}
_USENET_KEYS = ("usenet_enabled", "usenet_host", "usenet_port", "usenet_ssl", "usenet_user", "usenet_pass",
                "usenet_per_day", "usenet_index", "usenet_conns")
USENET_GROUPS = ("alt.binaries.teevee", "alt.binaries.hdtv.x264", "alt.binaries.x264", "alt.binaries.multimedia",
                 "alt.binaries.tv", "alt.binaries.movies", "alt.binaries.sounds.lossless", "alt.binaries.ebook",
                 "alt.binaries.e-book.technical")
USENET_BLOCK = 200_000               # headers read in one go
USENET_SETTLE = 30_000               # a release is taken as finished this many articles behind the reader
USENET_START = "2009-01-01"          # where a group is first read from: old posts carry readable names


async def _usenet_cfg(fresh: bool = False) -> dict:
    now = time.monotonic()
    if (fresh or now - _USENET["at"] > 5) and db_pool is not None:
        async with db_pool.acquire() as conn:
            rows = await conn.fetch("SELECT key, value FROM config WHERE key = ANY($1::text[])", list(_USENET_KEYS))
        d = {r["key"][7:]: r["value"] for r in rows}
        _USENET.update(at=now, cfg={
            "enabled": d.get("enabled") == "1", "host": (d.get("host") or "").strip(),
            "port": int(d.get("port") or 563), "ssl": d.get("ssl", "1") != "0",
            "user": d.get("user") or "", "pass": d.get("pass") or "",
            "per_day": max(0, int(d.get("per_day") or 2_000_000)),
            # With Usenet on, this install takes part in the shared index - as with Telegram,
            # what it finds is shared: names and pointers, never files. There is no switch for
            # that alone. "conns" is the most it is willing to use for reading the index; the
            # registry says how many it may (one for an ordinary install): the smaller is used.
            "index": d.get("enabled") == "1", "conns": max(1, min(int(d.get("conns") or 12), 20))})
    return _USENET["cfg"]


def _usenet_connect(cfg: dict):
    return usenet.NNTP(cfg["host"], cfg["port"], cfg["user"] or None, cfg["pass"] or None, use_ssl=cfg["ssl"])


def _usenet_try(cfg: dict) -> str:
    """'' when the server lets us in and answers, otherwise why not (never the account's name)."""
    try:
        nn = _usenet_connect(cfg)
    except usenet.NNTPError as e:
        return str(e)
    except Exception as e:
        return f"could not connect: {type(e).__name__}"
    try:
        nn.group("alt.binaries.teevee")
        return ""
    except Exception as e:
        return f"connected, but the server did not open a group: {e}"
    finally:
        nn.quit()


async def _usenet_ready(recheck: bool = False) -> bool:
    """Switched on, an account entered, and the server answered when last asked
    (asked again at most every ten minutes)."""
    cfg = await _usenet_cfg()
    if not (cfg.get("enabled") and cfg.get("host")):
        return False
    if recheck or _USENET["ok"] is None or time.monotonic() - _USENET["checked"] > 600:
        msg = await asyncio.to_thread(_usenet_try, cfg)
        _USENET.update(ok=not msg, msg=msg or "working", checked=time.monotonic())
    return bool(_USENET["ok"])


def _usenet_scan_block(cfg: dict, grp: str, start, asm, count: int):
    """Read `count` headers of a group from article `start` (None: from
    USENET_START), feed them to the group's assembler, and return the cards of
    the releases that are finished. Runs in a thread."""
    import calendar
    import random
    nn = _usenet_connect(cfg)
    try:
        _n, first, last = nn.group(grp)
        if start is None or start < first:
            start = usenet.article_at(nn, first, last, calendar.timegm(time.strptime(USENET_START, "%Y-%m-%d")))
        b0, lo, end = nn.bytes_in, start, min(last, start + count - 1)
        while lo <= end:
            for row in nn.over(lo, min(end, lo + 19999)):
                asm.add(*row)
            lo += 20000
        cursor, cards = end + 1, []
        for k, r in list(asm.rel.items()):
            if r["art_hi"] >= cursor - USENET_SETTLE and cursor <= last:
                continue                              # may still be arriving
            del asm.rel[k]
            c = usenet.card(r)
            if not c:
                continue
            ids = [m for f in r["files"].values() for m, _s in f["parts"].values()]
            sample = random.sample(ids, min(4, len(ids)))
            c["alive"] = round(sum(1 for m in sample if nn.stat(m)) / max(1, len(sample)), 2)
            cards.append(c)
        resume = min([r["art_lo"] for r in asm.rel.values()] + [cursor])
        return cards, cursor, max(resume, cursor - USENET_BLOCK), end - start + 1, nn.bytes_in - b0, first, last
    finally:
        nn.quit()


async def _usenet_scan_worker():
    """Reads a block of one group, then the next group, staying under the
    day's allowance of headers (their download is the cost: about 350 bytes
    each). Only while Usenet is switched on and the server answers."""
    await asyncio.sleep(90)
    logu = logging.getLogger("tgarr.usenet")
    asms, cursors, turn = {}, {}, 0
    while True:
        try:
            if not await _usenet_ready():
                await asyncio.sleep(300)
                continue
            cfg = await _usenet_cfg()
            day = time.strftime("%Y-%m-%d", time.gmtime())
            async with db_pool.acquire() as conn:
                used = await conn.fetchval("SELECT value FROM config WHERE key = 'usenet_today'") or ""
                rows = await conn.fetch("SELECT grp, next_article, enabled FROM usenet_progress")
            used_n = int(used.split(":")[1]) if used.startswith(day + ":") else 0
            room = cfg["per_day"] - used_n
            if room < 20000:
                await asyncio.sleep(900)
                continue
            known = {r["grp"]: r for r in rows}
            groups = [g for g in USENET_GROUPS if g not in known or known[g]["enabled"]]
            if not groups:
                await asyncio.sleep(900)
                continue
            grp = groups[turn % len(groups)]
            turn += 1
            start = cursors.get(grp, known[grp]["next_article"] if grp in known else None)
            asm = asms.setdefault(grp, usenet.Assembler(grp))
            try:
                cards, cursor, resume, n, nbytes, first, last = await asyncio.to_thread(
                    _usenet_scan_block, cfg, grp, start, asm, min(USENET_BLOCK, room))
            except Exception as e:
                logu.warning("[usenet] %s: %s", grp, str(e)[:120])
                async with db_pool.acquire() as conn:
                    await conn.execute(
                        """INSERT INTO usenet_progress (grp, note) VALUES ($1, $2)
                           ON CONFLICT (grp) DO UPDATE SET note = $2, updated_at = NOW()""", grp, str(e)[:200])
                await asyncio.sleep(120)
                continue
            cursors[grp] = cursor
            async with db_pool.acquire() as conn:
                await _usenet_store(conn, cards)
                await conn.execute(
                    """INSERT INTO usenet_progress (grp, first_article, last_article, next_article, headers, cards, bytes, note)
                       VALUES ($1, $2, $3, $4, $5, $6, $7, NULL)
                       ON CONFLICT (grp) DO UPDATE SET first_article = $2, last_article = $3, next_article = $4,
                           headers = usenet_progress.headers + $5, cards = usenet_progress.cards + $6,
                           bytes = usenet_progress.bytes + $7, note = NULL, updated_at = NOW()""",
                    grp, first, last, resume, n, len(cards), nbytes)
                await conn.execute(
                    """INSERT INTO config (key, value) VALUES ('usenet_today', $1)
                       ON CONFLICT (key) DO UPDATE SET value = $1, updated_at = NOW()""", f"{day}:{used_n + n}")
            logu.info("[usenet] %s: %s headers, %s cards, %.0f MB", grp, f"{n:,}", len(cards), nbytes / 1e6)
            await asyncio.sleep(20 if cursor <= last else 600)
        except Exception as e:
            logu.warning("[usenet] scanner: %s: %s", type(e).__name__, str(e)[:160])
            await asyncio.sleep(300)


_USENET_COLS = ("id", "name", "kind", "size", "grp", "poster", "posted_from", "posted_to", "files", "files_expected",
                "segments", "segments_expected", "complete", "first_message_id", "key", "art_lo", "art_hi", "alive")


async def _usenet_store(conn, cards: list) -> None:
    for c in cards:
        row = dict(c)
        row["grp"] = row.pop("group", row.get("grp"))
        await conn.execute(
            f"""INSERT INTO usenet_cards ({", ".join(_USENET_COLS)})
                VALUES ({", ".join(f"${i + 1}" for i in range(len(_USENET_COLS)))})
                ON CONFLICT (id) DO UPDATE SET size = EXCLUDED.size, files = EXCLUDED.files,
                    segments = EXCLUDED.segments, segments_expected = EXCLUDED.segments_expected,
                    complete = EXCLUDED.complete, art_lo = LEAST(usenet_cards.art_lo, EXCLUDED.art_lo),
                    art_hi = GREATEST(usenet_cards.art_hi, EXCLUDED.art_hi), alive = EXCLUDED.alive,
                    posted_to = EXCLUDED.posted_to""",
            *[bool(row.get(k)) if k == "complete" else row.get(k) for k in _USENET_COLS])


def _usenet_nzb(cfg: dict, c) -> str:
    """The NZB of one card, from the headers as they are on the server now. Runs in a thread."""
    nn = _usenet_connect(cfg)
    try:
        nn.group(c["grp"])
        asm = usenet.Assembler(c["grp"])
        lo, hi = c["art_lo"] - 2000, c["art_hi"] + 2000
        while lo <= hi:
            for r in nn.over(lo, min(hi, lo + 19999)):
                if usenet.poster_hash(r[2]) == c["poster"]:
                    p = usenet.parse_subject(r[1])
                    if p and usenet.release_key(p) == c["key"]:
                        asm.add(*r)
            lo += 20000
        rels = asm.releases()
        return usenet.build_nzb(rels[0]) if rels else ""
    finally:
        nn.quit()


_USENET_EP_RX = re.compile(r"S(\d{1,2})E(\d{1,3})", re.I)


def _usenet_item_xml(c, base_url: str, apikey: str) -> str:
    link = html.escape(f"{base_url}/newznab/usenet/api?t=get&id=un-{c['id']}&apikey={apikey}", quote=True)
    name, hd = c["name"], bool(re.search(r"\b(720|1080|2160)[pi]\b", c["name"], re.I))
    ep = _USENET_EP_RX.search(name)
    if c["kind"] == "video":
        cat = ("5040" if hd else "5030") if ep or re.search(r"\b\d{4}[. ]\d{2}[. ]\d{2}\b", name) else ("2040" if hd else "2030")
    else:
        cat = {"audio": "3010", "ebook": "7020"}.get(c["kind"], "8000")
    when = time.strftime("%a, %d %b %Y %H:%M:%S +0000", time.gmtime(c["posted_from"] or 0))
    attrs = f'      <newznab:attr name="category" value="{cat}"/>\n      <newznab:attr name="size" value="{c["size"] or 0}"/>\n'
    if ep and cat.startswith("5"):
        attrs += (f'      <newznab:attr name="season" value="{int(ep.group(1))}"/>\n'
                  f'      <newznab:attr name="episode" value="{int(ep.group(2))}"/>\n')
    attrs += f'      <newznab:attr name="group" value="{html.escape(c["grp"])}"/>\n'
    return (f"    <item>\n      <title>{html.escape(name)}</title>\n"
            f"      <guid isPermaLink=\"false\">un-{c['id']}</guid>\n      <link>{link}</link>\n"
            f"      <pubDate>{when}</pubDate>\n      <category>{cat}</category>\n      <size>{c['size'] or 0}</size>\n"
            f"      <description>Usenet, {html.escape(c['grp'])}</description>\n"
            f"      <enclosure url=\"{link}\" length=\"{c['size'] or 0}\" type=\"application/x-nzb\"/>\n{attrs}    </item>")


@app.get("/newznab/usenet/api", response_class=PlainTextResponse)
@app.get("/newznab/usenet", response_class=PlainTextResponse)
async def newznab_usenet(request: Request, t: str = Query("search"), q: Optional[str] = Query(None),
                         season: Optional[str] = None, ep: Optional[str] = None, cat: Optional[str] = None,
                         limit: int = 100, offset: int = 0, apikey: Optional[str] = "tgarr",
                         id: Optional[str] = None):
    base_url = _base_url(request)
    if t == "caps":
        return Response(CAPS_XML, media_type="application/xml")
    if t not in ("search", "tvsearch", "movie", "get"):
        return _newznab_error(202, f"No such function ({t})")
    # Nothing is offered unless Usenet is switched on and the server answers:
    # a result that cannot be turned into an NZB is worse than no result.
    if not await _usenet_ready():
        if t == "get":
            return _newznab_error(300, "Usenet is switched off or the news server is not answering", 503)
        return Response(_feed_envelope("", "usenet (off)", base_url), media_type="application/xml")
    if t == "get":
        if not id or not re.fullmatch(r"un-[0-9a-f]{20}", id):
            return _newznab_error(300, "No such item", 404)
        async with db_pool.acquire() as conn:
            c = await conn.fetchrow("SELECT * FROM usenet_cards WHERE id = $1", id[3:])
        if not c or usenet_rules.forbidden({"name": c["name"], "groups": [c["grp"]], "audience": c["audience"]}):
            return _newznab_error(300, "No such item", 404)
        try:
            if c["sketch"]:
                _ucfg = await _usenet_cfg()
                # as many connections as the provider gives: somebody is waiting for this.
                # The number finds its own level (usenet_scan.next_connections) and is kept.
                async with db_pool.acquire() as conn:
                    _asked = usenet_scan.next_connections(
                        await conn.fetchval("SELECT value FROM config WHERE key = 'usenet_nzb_conns'"), {})
                _UN_INDEX["nzb"] += 1                        # the index reading stands aside meanwhile
                try:
                    got = await asyncio.to_thread(
                        usenet_scan.rebuild, _ucfg, c["grp"], c["poster"], c["key"], c["art_lo"], c["art_hi"],
                        6000 if c["detail"] == 0 else 2000, c["name"], _asked)
                finally:
                    _UN_INDEX["nzb"] -= 1
                _next = usenet_scan.next_connections(_asked, got)
                if _next != _asked:
                    async with db_pool.acquire() as conn:
                        await conn.execute("""INSERT INTO config (key, value) VALUES ('usenet_nzb_conns', $1)
                                              ON CONFLICT (key) DO UPDATE SET value = $1, updated_at = NOW()""", str(_next))
                text = got["nzb"]
                logging.getLogger("tgarr").info(
                    "[usenet] NZB for %s: %s parts of %s file(s) in %.1fs over %s connection(s) of %s asked, %s request(s)%s%s",
                    c["id"], f"{got['segments']:,}", got["files"], got.get("seconds", 0), got.get("connections", 1), _asked,
                    got.get("requests", 0), f", {got['unread']} stretch(es) the server did not give" if got.get("unread") else "",
                    f"; {_next} next time" if _next != _asked else "")
                if text and not got.get("unread"):           # now it has been read in full: keep the exact figures
                    async with db_pool.acquire() as conn:
                        await conn.execute(
                            """UPDATE usenet_cards SET size = $2, files = $3, segments = $4, complete = $5,
                                      art_lo = $6, art_hi = $7, detail = 1 WHERE id = $1""",
                            c["id"], got["size"], got["files"], got["segments"], got["complete"], got["art_lo"], got["art_hi"])
            else:
                text = await asyncio.to_thread(_usenet_nzb, await _usenet_cfg(), c)
        except Exception as e:
            _USENET.update(ok=None)                          # look at the server again before the next answer
            return _newznab_error(300, f"The news server did not give the headers: {str(e)[:80]}", 503)
        if not text:
            return _newznab_error(300, "This release is no longer on the news server", 404)
        safe = "".join(ch if ord(ch) < 128 and ch not in '"\\' else "_" for ch in c["name"])[:150]
        return Response(text, media_type="application/x-nzb",
                        headers={"Content-Disposition": f'attachment; filename="{safe}.nzb"'})
    where, params = ["alive >= 0.5"], []
    for w in re.split(r"[\s.]+", q or "")[:8]:
        if w:
            params.append("%" + w.replace("%", "").replace("_", r"\_") + "%")
            where.append(f"name ILIKE ${len(params)}")
    if t == "tvsearch":
        where.append(r"kind = 'video' AND name ~* 'S\d{1,2}E\d{1,3}|\d{4}[. ]\d{2}[. ]\d{2}'")
        def _n(v):
            return int(v) if v and v.isascii() and v.isdigit() and len(v) < 6 else None
        day = re.fullmatch(r"(\d{1,2})/(\d{1,2})", ep or "")
        if _n(season) is not None and day:
            # a show named by its date: 2026.11.15, 2026-11-15, 2026 11 15
            params.append(rf"{_n(season)}[. _-]0?{int(day.group(1))}[. _-]0?{int(day.group(2))}(?!\d)")
            where.append(f"name ~* ${len(params)}")
        elif _n(season) is not None and _n(ep) is not None:
            params.append(rf"S0*{_n(season)}E0*{_n(ep)}(?!\d)")
            where.append(f"name ~* ${len(params)}")
        elif _n(season) is not None:
            params.append(rf"S0*{_n(season)}(E\d|\M)")
            where.append(f"name ~* ${len(params)}")
    elif t == "movie":
        where.append(r"kind = 'video' AND name !~* 'S\d{1,2}E\d{1,3}'")
    else:
        where.append("kind IN ('video', 'audio', 'ebook')")
    if not await _is_nsfw_enabled():
        where.append("audience <> 'nsfw'")             # adult material only where it is switched on
    lim = max(1, min(int(limit), 200))
    await _usenet_from_registry(q or "")
    async with db_pool.acquire() as conn:
        rows = await conn.fetch(
            f"""SELECT *, count(*) OVER() AS _total FROM usenet_cards WHERE {' AND '.join(where)}
                ORDER BY complete DESC, posted_from DESC NULLS LAST LIMIT {lim} OFFSET {max(0, int(offset))}""", *params)
    rows = [r for r in rows if not usenet_rules.forbidden({"name": r["name"], "groups": [r["grp"]], "audience": r["audience"]})]
    items = "\n".join(_usenet_item_xml(r, base_url, apikey or "tgarr") for r in rows)
    return Response(_feed_envelope(items, f"usenet t={t} q={q or ''}", base_url, offset=max(0, int(offset)),
                                   total=rows[0]["_total"] if rows else 0), media_type="application/xml")


# ════════════════════════════════════════════════════════════════════
# Taking part in the shared Usenet index (docs/USENET_INDEX.md).
#
# On whenever Usenet is on - there is no switch of its own. The registry
# leases this install a window - a group and a stretch of time - and says
# how to read it (sparsely at first: a few headers every couple of thousand
# articles). The window is read over several connections, the releases seen
# are sketched into cards, the cards are kept here (so this install's own
# Sonarr finds them at once) and handed in. Searches ask the registry as
# well and keep what it knows. Only headers are ever read; an NZB is made
# when somebody asks for one.
# ════════════════════════════════════════════════════════════════════
_UN_INDEX = {"state": "off", "window": None, "at": 0.0, "last": None, "asked": {}, "nzb": 0}
_UN_SKETCH_COLS = ("id", "name", "kind", "size", "grp", "poster", "posted_from", "posted_to", "files", "files_expected",
                   "segments", "complete", "first_message_id", "key", "art_lo", "art_hi", "alive", "sketch", "detail", "audience")


async def _usenet_tidy() -> dict:
    """The cards kept here brought into line with usenet_rules as they are now: adult ones
    labelled, those that are never kept deleted. At start and after cards are taken in -
    whatever way they came (this install's own reading, the older scanner, the registry)."""
    R = usenet_rules
    async with db_pool.acquire() as conn:
        labelled = await conn.execute(
            "UPDATE usenet_cards SET audience = 'nsfw' WHERE audience <> 'nsfw' AND (name ~* $1 OR grp ~* $2)",
            R.ADULT_NAME_SQL, R.ADULT_GROUP_SQL)
        gone = await conn.execute(
            """DELETE FROM usenet_cards WHERE name ~* $1 OR grp ~* $2 OR (audience = 'nsfw' AND name ~* $3)""",
            R.FORBIDDEN_SQL, R.GROUP_FORBIDDEN_SQL, R.MINOR_SQL)
    out = {"labelled_adult": int(labelled.split()[-1]), "deleted": int(gone.split()[-1])}
    if out["labelled_adult"] or out["deleted"]:
        logging.getLogger("tgarr").info("[usenet] cards put in line with the rules: %s", out)
    return out


async def _instance_uuid() -> str:
    import uuid as _uuid
    async with db_pool.acquire() as conn:
        v = await conn.fetchval("SELECT value FROM config WHERE key = 'instance_uuid'")
        if not v:
            v = str(_uuid.uuid4())
            await conn.execute("INSERT INTO config (key, value) VALUES ('instance_uuid', $1) ON CONFLICT (key) DO NOTHING", v)
            v = await conn.fetchval("SELECT value FROM config WHERE key = 'instance_uuid'")
    return v


def _usenet_card_id(poster: str, key: str) -> str:
    return hashlib.sha1(f"{poster}|{key}".encode("utf-8", "replace")).hexdigest()[:20]      # as the registry counts them


async def _usenet_keep(cards: list) -> int:
    """Sketched cards into this install's own table, in one go."""
    rows = []
    for c in cards:
        grp = c.get("grp") or c["groups"][0]
        judged = {"name": c["name"], "inner_name": c.get("inner_name"), "groups": list(c.get("groups") or ()) + [grp],
                  "audience": c.get("audience")}
        # wherever the card came from - this install's reading or the registry - it is judged here
        if CSAM_RX.search(c["name"]) or usenet_rules.forbidden(judged) or not c.get("art_lo"):
            continue
        rows.append((_usenet_card_id(c["poster"], c["key"]), c["name"][:300], c["kind"], c.get("size"), grp,
                     c["poster"], c.get("posted_from"), c.get("posted_to"), c.get("files"), c.get("files_expected"),
                     c.get("segments"), c.get("complete"), c["first_message_id"], c["key"], c["art_lo"], c["art_hi"], 1.0, True,
                     0 if c.get("detail") == 0 else 1,
                     "nsfw" if (c.get("audience") == "nsfw" or usenet_rules.adult(judged)) else "sfw"))
    if not rows:
        return 0
    cols = ", ".join(_UN_SKETCH_COLS)
    async with db_pool.acquire() as conn:
        async with conn.transaction():
            await conn.execute("CREATE TEMP TABLE _uk (LIKE usenet_cards INCLUDING DEFAULTS) ON COMMIT DROP")
            await conn.copy_records_to_table("_uk", columns=list(_UN_SKETCH_COLS), records=rows)
            await conn.execute(
                f"""INSERT INTO usenet_cards ({cols}) SELECT DISTINCT ON (id) {cols} FROM _uk
                    ON CONFLICT (id) DO UPDATE SET
                      art_lo = LEAST(usenet_cards.art_lo, EXCLUDED.art_lo), art_hi = GREATEST(usenet_cards.art_hi, EXCLUDED.art_hi),
                      -- what was read in full is not put back to an estimate
                      size = CASE WHEN usenet_cards.detail > EXCLUDED.detail THEN usenet_cards.size ELSE EXCLUDED.size END,
                      detail = GREATEST(usenet_cards.detail, EXCLUDED.detail), alive = 1.0, sketch = TRUE,
                      audience = CASE WHEN EXCLUDED.audience = 'nsfw' THEN 'nsfw' ELSE usenet_cards.audience END""")
    return len(rows)


def _usenet_index_window(cfg: dict, w: dict) -> dict:
    """Read one leased window. Runs in a thread (it takes minutes)."""
    import calendar as _cal
    nn = usenet_scan.connect(cfg, packed=False)
    try:
        count, first, last = nn.group(w["grp"])
        # the oldest article the provider has: a window before that has nothing in it here
        oldest = None
        for hop in range(6):
            for r in nn.over(first + hop * 3000, first + hop * 3000 + 49):
                oldest = usenet.when(r[3])
                if oldest:
                    break
            if oldest:
                break
        if count <= 0 or (oldest and w["t_to"] <= oldest):
            return {"empty": True, "stats": {"headers": 0, "bytes": 0, "seconds": 0}, "posters": [], "cards": [],
                    "oldest": time.strftime("%Y-%m-%d", time.gmtime(oldest)) if oldest else None}
        lo = usenet.article_at(nn, first, last, w["t_from"])
        hi = usenet.article_at(nn, first, last, w["t_to"])
    finally:
        try:
            nn.sock.close()
        except Exception:
            pass
    sparse = tuple(w["read"]) if w.get("read") else None
    sk = usenet_scan.Sketch(w["grp"], items=not sparse)
    # how many connections: never more than the registry allows this install (one, unless it
    # is told otherwise), and never more than is set here
    allowed = max(1, min(int(w.get("connections") or 1), 20))
    # subjects are judged on a thread of their own as they arrive: the reading threads are
    # not held up, and a window read in full (millions of headers) is never held in memory
    feed = usenet_scan.Feeder(sk.add_rows)
    try:
        st = usenet_scan.read_window(cfg, w["grp"], lo, max(lo, hi), read=sparse,
                                     connections=max(1, min(cfg.get("conns", 1), allowed)), on_rows=feed.put,
                                     hold=lambda: _UN_INDEX["nzb"] > 0)
    finally:
        feed.close()
    if st["failed"] and len(st["failed"]) * 10 > st["requests"] + len(st["failed"]):
        # more than a tenth of it unread: this is not a reading of the window. Hand nothing
        # in (the lease runs out and the window is offered again) rather than call it read.
        raise usenet.NNTPError(f"{len(st['failed'])} of {st['requests'] + len(st['failed'])} stretches could not be read")
    cards = sk.cards(detail=0 if sparse else 1, min_size=100_000_000 if sparse else 0)
    for c in cards:
        c["grp"] = w["grp"]
    c_ = sk.count
    return {"empty": st["headers"] == 0, "posters": sk.poster_lines(), "cards": cards, "range": (lo, hi),
            "oldest": time.strftime("%Y-%m-%d", time.gmtime(oldest)) if oldest else None,
            "stats": {"headers": st["headers"], "bytes": st["bytes"], "seconds": st["seconds"], "requests": st["requests"],
                      "unread": len(st["failed"]), "connections": st["connections"],
                      "wanted": c_["wanted"], "unknown": c_["unknown"], "hidden": c_["hidden"] + c_["password"],
                      "not_part": c_["not a part"]}}


async def _usenet_index_worker():
    logu = logging.getLogger("tgarr")
    await asyncio.sleep(40)
    tidied = 0.0
    failed = {}                                    # window id -> when reading it last failed
    while True:
        w = None
        try:
            if time.time() - tidied > 3600:            # at start, and every hour: whatever way cards came in
                tidied = time.time()
                try:
                    await _usenet_tidy()
                except Exception as e:
                    logu.warning("[usenet] tidy: %s", e)
            cfg = await _usenet_cfg(fresh=True)
            if not (cfg.get("index") and cfg.get("enabled") and cfg.get("host")):
                _UN_INDEX["state"] = "off"
                await asyncio.sleep(120)
                continue
            if not await _usenet_ready():
                _UN_INDEX["state"] = "the news server is not answering"
                await asyncio.sleep(300)
                continue
            uuid_ = await _instance_uuid()
            wins = await asyncio.to_thread(usenet_client.lease, UPDATE_REGISTRY_URL, uuid_, TGARR_VERSION, cfg["host"], None, 0)
            # A window that could not be read is left alone for six hours. The registry gives
            # back what an install still holds, so without this one bad window was handed out
            # again every ten minutes and nothing else was ever read.
            wins = [x for x in wins if time.time() - failed.get(x["id"], 0) > 6 * 3600]
            if not wins:
                _UN_INDEX["state"] = "nothing to do right now"
                await asyncio.sleep(1800)
                continue
            w = wins[0]
            if usenet_rules.group_never(w["grp"]):
                # tgarr.me does not hand such a group out; should one arrive all the same,
                # it is not read (the lease runs out)
                _UN_INDEX["state"] = "was handed a group that is not read; waiting"
                await asyncio.sleep(3600)
                continue
            _UN_INDEX.update(state="reading", window=w, at=time.time())
            logu.info("[usenet-index] window %s: %s %s, %s", w["id"], w["grp"],
                      time.strftime("%Y-%m-%d", time.gmtime(w["t_from"])), w["mode"])
            res = await asyncio.to_thread(_usenet_index_window, cfg, w)
            kept = await _usenet_keep(res["cards"])
            out = await asyncio.to_thread(
                usenet_client.report, UPDATE_REGISTRY_URL, uuid_, TGARR_VERSION, cfg["host"], w["id"], res["stats"],
                res["posters"], [{k: v for k, v in c.items() if k != "grp"} for c in res["cards"]], res["empty"])
            _UN_INDEX.update(state="idle", last={"window": w["id"], "grp": w["grp"], "mode": w["mode"], "cards": len(res["cards"]),
                                                  "kept": kept, "accepted": out["accepted"], "refused": out["refused"],
                                                  "stats": res["stats"], "at": time.time()})
            logu.info("[usenet-index] window %s done: %s headers in %ss (%.1f MB), %s cards, registry took %s, refused %s",
                      w["id"], f"{res['stats']['headers']:,}", res["stats"]["seconds"], res["stats"]["bytes"] / 1e6,
                      len(res["cards"]), out["accepted"], out["refused"])
            await asyncio.sleep(5)
        except Exception as e:
            _UN_INDEX["state"] = f"waiting after a problem: {type(e).__name__}: {str(e)[:120]}"
            logu.warning("[usenet-index] %s: %s", type(e).__name__, str(e)[:200])
            if w is not None:
                if len(failed) > 500:
                    failed.clear()
                failed[w["id"]] = time.time()
                await asyncio.sleep(60)            # this window is set aside: on to the next one
            else:
                await asyncio.sleep(600)           # the registry or the settings: wait


async def _usenet_from_registry(q: str) -> int:
    """Before answering a search: what the registry knows for these words, kept here when it
    can be fetched through this install's provider. At most once in ten minutes per question,
    and never longer than a few seconds - the answer must not wait on the registry."""
    cfg = await _usenet_cfg()
    q = (q or "").strip().lower()
    if not (cfg.get("index") and cfg.get("host") and len(q) >= 3):
        return 0
    now = time.time()
    if now - _UN_INDEX["asked"].get(q, 0) < 600:
        return 0
    if len(_UN_INDEX["asked"]) > 2000:
        _UN_INDEX["asked"].clear()
    _UN_INDEX["asked"][q] = now
    try:
        cards = await asyncio.wait_for(asyncio.to_thread(usenet_client.search, UPDATE_REGISTRY_URL, cfg["host"], q), 6)
    except Exception:
        return 0
    return await _usenet_keep([c for c in cards if c.get("art_lo") and c.get("grp")])


# ════════════════════════════════════════════════════════════════════
# Small things fetched from Usenet by tgarr itself (usenet_fetch.py)
#
# A book, a song, a picture that was posted whole: fetched part by part, checked, and put
# in a folder of this machine that is one more "chat" (as My files is), so the Library,
# Music, the Gallery, the search and the Media Center show it like anything else. Never
# video, nothing packed, never a program. One asking at a time, over at most four
# connections; the reading of the index stands aside meanwhile. Adult cards go to a
# folder of their own that is labelled 18+.
# ════════════════════════════════════════════════════════════════════
USENET_ROOT, USENET_ROOT_ADULT = "usenet", "usenet18"
_UN_GRAB_KINDS = ("ebook", "audio", "photo")
# The shelves of the Usenet page. A card only knows "ebook" or "audio"; which shelf it stands
# on is read from where it was posted and what it is called. One rule, in SQL for the page
# and in Python for the folder a fetch lands in - test_usenet_shelf keeps them the same.
_UN_SHELVES = (("ebook", "📖", "Books"), ("comic", "💬", "Comics"), ("magazine", "📰", "Magazines"),
               ("audiobook", "🎧", "Audiobooks"), ("audio", "🎵", "Music"), ("photo", "🖼", "Pictures"))
_UN_AUDIOBOOK_GRP, _UN_AUDIOBOOK_NAME = r"audiobook|\.books$|hoorspel", r"audio ?book|unabridged|\.m4b"
_UN_COMIC_GRP, _UN_COMIC_NAME, _UN_MAGAZINE_GRP = r"comic", r"\.cb[zr]", r"magazine"
_UN_SHELF_SQL = f"""CASE
    WHEN c.kind = 'audio' AND (c.grp ~ '{_UN_AUDIOBOOK_GRP}' OR c.name ~* '{_UN_AUDIOBOOK_NAME}') THEN 'audiobook'
    WHEN c.kind = 'ebook' AND (c.grp ~ '{_UN_COMIC_GRP}' OR c.name ~* '{_UN_COMIC_NAME}') THEN 'comic'
    WHEN c.kind = 'ebook' AND c.grp ~ '{_UN_MAGAZINE_GRP}' THEN 'magazine'
    ELSE c.kind END"""


def _un_shelf(kind: str, grp: str, name: str) -> str:
    grp, name = grp or "", name or ""
    if kind == "audio" and (re.search(_UN_AUDIOBOOK_GRP, grp) or re.search(_UN_AUDIOBOOK_NAME, name, re.I)):
        return "audiobook"
    if kind == "ebook" and (re.search(_UN_COMIC_GRP, grp) or re.search(_UN_COMIC_NAME, name, re.I)):
        return "comic"
    if kind == "ebook" and re.search(_UN_MAGAZINE_GRP, grp):
        return "magazine"
    return kind
_UN_FOLDER = {"ebook": "books", "audio": "music", "photo": "pictures",
              "comic": "comics", "magazine": "magazines", "audiobook": "audiobooks"}


def _un_single_name(release: str, file_name: str) -> str:
    """The name one file alone is kept under. A post often calls its file something that
    says nothing by itself ("AlbumArtLarge.jpg", "(1975-04-28)(c2c).cbz"): then the name of
    the release goes in front."""
    def flat(s):
        return re.sub(r"[^a-z0-9]+", "", (s or "").lower())
    stem, dot, ext = (file_name or "").rpartition(".")
    if not dot:
        stem, ext = file_name or "", ""
    rel = re.sub(r"\.[A-Za-z0-9]{2,5}$", "", (release or "").strip())
    if not flat(rel) or flat(rel) in flat(stem) or (len(flat(stem)) >= 8 and flat(stem) in flat(rel)):
        return file_name
    return f"{rel} {stem}"[:150].strip() + (("." + ext) if ext else "")
_UN_GRAB = {"now": None, "bytes": 0, "of": 0}


def _usenet_grab_files(cfg: dict, take: list, folder: str, progress, refused=None) -> list:
    """In a thread: the files of one release over up to four connections.
    [(path, size)] of those that arrived whole. `refused(name)`: asked with the name a post
    gives its file inside (it can differ from the subject line) - true, and the file is
    not kept."""
    import queue
    import threading
    todo = queue.Queue()
    for f in take:
        todo.put(dict(f, tries=0))
    done, names, lock = [], set(), threading.Lock()

    def work():
        try:
            nn = _usenet_connect(cfg)
        except Exception:
            return
        try:
            while True:
                try:
                    f = todo.get_nowait()
                except queue.Empty:
                    return
                with lock:
                    name = localfiles.free_name(lambda x: x in names or os.path.exists(os.path.join(folder, x)),
                                                localfiles.safe_name(f["name"]))
                    names.add(name)
                try:
                    got = usenet_fetch.fetch_file(nn.body, f, os.path.join(folder, name), progress)
                    if refused and refused(got["name"]):
                        os.unlink(os.path.join(folder, name))
                        continue
                    with lock:
                        done.append((os.path.join(folder, name), got["size"]))
                except usenet_fetch.Missing:
                    pass
                except (usenet.NNTPError, OSError):
                    if f["tries"] < 2:             # the connection went: another one takes the file
                        todo.put(dict(f, tries=f["tries"] + 1))
                    return
        finally:
            nn.quit()
    for round_ in range(3):                        # a connection that went leaves its file for the next round
        if todo.empty():
            break
        threads = [threading.Thread(target=work, daemon=True) for _ in range(max(1, min(4, todo.qsize())))]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
    return done


async def _usenet_grab_one(job) -> tuple:
    """(state, note, files, bytes, message id of the first file)."""
    import collections
    import shutil
    async with db_pool.acquire() as conn:
        c = await conn.fetchrow("SELECT * FROM usenet_cards WHERE id = $1", job["card_id"])
    if (not c or c["kind"] not in _UN_GRAB_KINDS or CSAM_RX.search(c["name"])
            or usenet_rules.forbidden({"name": c["name"], "groups": [c["grp"]], "audience": c["audience"]})):
        return "failed", "it is no longer in the index", 0, 0, None
    cfg = await _usenet_cfg()
    base = None
    _UN_INDEX["nzb"] += 1                          # the index reading stands aside meanwhile
    try:
        if c["sketch"]:
            got = await asyncio.to_thread(
                usenet_scan.rebuild, cfg, c["grp"], c["poster"], c["key"], c["art_lo"], c["art_hi"],
                6000 if c["detail"] == 0 else 2000, c["name"], 4)
            text = got["nzb"]
        else:
            text = await asyncio.to_thread(_usenet_nzb, cfg, c)
        if not text:
            return "failed", "it is no longer on the news server", 0, 0, None
        inside = usenet_fetch.parse_nzb(text)
        adult = c["audience"] == "nsfw"
        # the guard, on everything the release holds - also what would not be taken: one
        # file named for it and none of the release is fetched, and its card goes
        why = next((w for w in (usenet_rules.never_kept([f["name"], f["subject"], c["name"]], [c["grp"]], adult) for f in inside) if w), "")
        if why or any(CSAM_RX.search(f["name"] or "") or CSAM_RX.search(f["subject"] or "") for f in inside):
            await _usenet_blocked("release", why or "a term for it in its name", c["name"])
            async with db_pool.acquire() as conn:
                await conn.execute("DELETE FROM usenet_cards WHERE id = $1", c["id"])
            return "failed", "never fetched: the block list", 0, 0, None
        p = usenet_fetch.plan(inside)
        take = [f for f in p["take"] if not usenet_judge.is_program(f["name"])]
        if not take:
            return "failed", p["why"] or "nothing in it that can be opened as it is", 0, 0, None
        want = int(sum(f["bytes"] for f in take) * 0.97)
        if want > shutil.disk_usage("/downloads").free - (1 << 30):
            return "failed", "not enough room left on the disk", 0, 0, None
        root = USENET_ROOT_ADULT if adult else USENET_ROOT
        kind = collections.Counter(f["kind"] for f in take).most_common(1)[0][0]
        base = f"/downloads/{root}/{_UN_FOLDER[_un_shelf(kind, c['grp'], c['name'])]}"
        os.makedirs(base, exist_ok=True)
        if len(take) == 1:
            take = [dict(take[0], name=_un_single_name(c["name"], take[0]["name"]))]
        if len(take) > 1:                          # an album, a set of pictures: a folder of its own
            base = os.path.join(base, localfiles.free_name(lambda x: os.path.exists(os.path.join(base, x)),
                                                           localfiles.safe_name(c["name"])[:120].strip(" .") or "release"))
            os.makedirs(base, exist_ok=True)
        _UN_GRAB.update(now=job["id"], bytes=0, of=want)

        def progress(n):
            _UN_GRAB["bytes"] += n
        struck = []

        def refused(inner):
            if usenet_rules.never_kept([inner, c["name"]], [c["grp"]], adult) or CSAM_RX.search(inner or ""):
                struck.append(inner)
                return True
            return False
        done = await asyncio.to_thread(_usenet_grab_files, cfg, take, base, progress, refused)
        for inner in struck:
            await _usenet_blocked("file", "a name inside the post", inner)
    finally:
        _UN_INDEX["nzb"] -= 1
        _UN_GRAB["now"] = None
    if not done:
        if len(take) > 1:
            try:
                os.rmdir(base)
            except OSError:
                pass
        return "failed", "it is no longer whole on the news server", 0, 0, None
    now = int(time.time())
    rels = [(os.path.relpath(path, "/downloads").replace(os.sep, "/"), size, now) for path, size in sorted(done)]
    async with db_pool.acquire() as conn:
        await _local_add(conn, root, rels)
        await conn.execute("UPDATE messages SET caption = $2, usenet_grp = $3 WHERE local_path = ANY($1::text[])",
                           [r[0] for r in rels], _un_caption(c["name"], c["grp"], c["posted_from"]), c["grp"])
        if adult:
            await conn.execute("UPDATE channels SET audience = 'nsfw', audience_manual = TRUE WHERE tg_chat_id = $1",
                               localfiles.chat_id(root))
        mid = await conn.fetchval("SELECT id FROM messages WHERE local_path = $1 ORDER BY id DESC LIMIT 1", rels[0][0])
    whole = len(done) == len(take)
    return ("done" if whole else "partial", "" if whole else f"{len(done)} of {len(take)} files arrived whole",
            len(done), sum(sz for _p, sz in done), mid)


async def _usenet_blocked(what: str, why: str, name: str) -> None:
    log.warning("[guard] %s refused or removed: %s", what, why)
    try:
        async with db_pool.acquire() as conn:
            await conn.execute("INSERT INTO usenet_blocked (what, why, name) VALUES ($1, $2, $3)", what, why, (name or "")[:300])
    except Exception:
        pass


_UN_GUARD = {"at": 0.0}


async def _usenet_guard_sweep() -> int:
    """What was fetched before, held against the rules as they are now. Every name a file
    has is read - its own, its folder, its caption (release, newsgroup) - and a picture
    found to be adult by looking at it counts as adult whatever its folder says. What
    fails is removed from the disk and from the library, and written down."""
    _UN_GUARD["at"] = time.time()
    async with db_pool.acquire() as conn:
        rows = await conn.fetch(
            f"""SELECT m.id, m.channel_id, m.file_name, m.caption, m.local_path, m.ai_adult, c.audience, c.local_root
                FROM messages m JOIN channels c ON c.id = m.channel_id
                WHERE {_FROM_USENET} AND m.local_path IS NOT NULL AND left(m.local_path, 2) <> '__'""")
    gone = []
    for r in rows:
        cap = [x.strip() for x in (r["caption"] or "").split(" · ")]
        groups = [x for x in cap if re.match(r"^[a-z0-9+_-]+(\.[a-z0-9+_-]+){2,}$", x)]
        adult = r["local_root"] == USENET_ROOT_ADULT or r["audience"] == "nsfw" or (r["ai_adult"] or 0) >= 0.9
        why = usenet_rules.never_kept([r["file_name"], r["local_path"]] + [x for x in cap if x not in groups], groups, adult)
        if not why and any(CSAM_RX.search(x or "") for x in (r["file_name"], r["caption"], r["local_path"])):
            why = "a term for it in its name"
        if why:
            gone.append((r, why))
    for r, why in gone:
        path = os.path.join("/downloads", r["local_path"])
        try:
            os.unlink(path)
        except OSError:
            pass
        try:                                       # a folder left empty goes too
            os.rmdir(os.path.dirname(path))
        except OSError:
            pass
        async with db_pool.acquire() as conn:
            await _local_forget(conn, r["channel_id"], [r["local_path"]])
        await _usenet_blocked("kept file", why, r["local_path"])
    if gone:
        _KID_OK.clear()
    return len(gone)


def _un_caption(name, grp, posted) -> str:
    """What stands under a file fetched from Usenet: its release, its newsgroup, the day it
    was posted. The file's own name is shown beside it."""
    return " · ".join(x for x in ((name or "").strip()[:200], grp or "",
                                  ("posted " + time.strftime("%Y-%m-%d", time.gmtime(posted))) if posted else "") if x)


async def _usenet_captions_once() -> None:
    """Fetches made before captions were written get theirs: the files of a release lie in
    one folder (or it is one file), and the fetch knows one of them."""
    async with db_pool.acquire() as conn:
        for g in await conn.fetch(
                """SELECT m.id, m.local_path, c.name, c.grp, c.posted_from FROM usenet_grabs g
                   JOIN messages m ON m.id = g.msg_id JOIN usenet_cards c ON c.id = g.card_id
                   WHERE g.state IN ('done', 'partial') AND m.caption IS NULL AND m.local_path IS NOT NULL"""):
            cap = _un_caption(g["name"], g["grp"], g["posted_from"])
            folder = os.path.dirname(g["local_path"])
            if folder.count("/") >= 2:             # usenet/pictures/<release>/file
                await conn.execute("UPDATE messages SET caption = $2 WHERE caption IS NULL AND left(local_path, $3) = $1",
                                   folder + "/", cap, len(folder) + 1)
            else:
                await conn.execute("UPDATE messages SET caption = $2 WHERE id = $1", g["id"], cap)
        # and the newsgroup, for those fetched before it was written down: it is the part
        # of the caption that reads like one ("alt.binaries.pictures.x")
        await conn.execute(
            f"""UPDATE messages m SET usenet_grp = x.g FROM
                  (SELECT m2.id, (SELECT s FROM unnest(string_to_array(m2.caption, ' · ')) s
                                  WHERE s ~ '^[a-z0-9+_-]+(\\.[a-z0-9+_-]+){{2,}}$' LIMIT 1) AS g
                   FROM messages m2 JOIN channels c ON c.id = m2.channel_id
                   WHERE {_FROM_USENET} AND m2.usenet_grp IS NULL AND m2.caption IS NOT NULL) x
                WHERE x.id = m.id AND x.g IS NOT NULL""")


async def _usenet_grab_worker():
    await asyncio.sleep(40)
    try:
        async with db_pool.acquire() as conn:      # what a restart interrupted starts over
            await conn.execute("UPDATE usenet_grabs SET state = 'queued' WHERE state = 'working'")
        await _usenet_captions_once()
    except Exception:
        log.exception("[usenet] could not tidy up after a restart")
    while True:
        try:
            async with db_pool.acquire() as conn:
                job = await conn.fetchrow(
                    """UPDATE usenet_grabs SET state = 'working' WHERE id =
                       (SELECT id FROM usenet_grabs WHERE state = 'queued' ORDER BY id LIMIT 1) RETURNING *""")
            if not job:
                # at start, and every quarter of an hour after: pictures are looked at
                # later than they are fetched, and a verdict changes what a name means
                if time.time() - _UN_GUARD["at"] > 900:
                    n_gone = await _usenet_guard_sweep()
                    if n_gone:
                        log.warning("[guard] the sweep removed %d kept file(s)", n_gone)
                await asyncio.sleep(3)
                continue
            try:
                res = await _usenet_grab_one(job)
            except Exception as e:
                log.warning("[usenet] fetching %s: %s: %s", job["card_id"], type(e).__name__, str(e)[:160])
                _USENET.update(ok=None)
                res = ("failed", "the news server did not answer - try again later", 0, 0, None)
            async with db_pool.acquire() as conn:
                await conn.execute(
                    "UPDATE usenet_grabs SET state = $2, note = $3, files = $4, bytes = $5, msg_id = $6, done_at = NOW() WHERE id = $1",
                    job["id"], *res)
            _UN_GUARD["at"] = 0.0                    # what just came in is swept at once
            log.info("[usenet] fetched %s (%s): %s%s, %s file(s), %s", job["card_id"], job["name"][:60], res[0],
                     f" - {res[1]}" if res[1] else "", res[2], _fmt_size(res[3]) or "0")
        except Exception as e:
            log.warning("[usenet] the fetching: %s: %s", type(e).__name__, str(e)[:160])
            await asyncio.sleep(20)


@app.post("/api/usenet/grab")
async def api_usenet_grab(request: Request):
    def no(msg, code=400):
        return JSONResponse({"status": "error", "message": msg}, status_code=code)
    try:
        cid = str((await request.json()).get("id") or "")
    except Exception:
        cid = ""
    if not re.fullmatch(r"[0-9a-f]{20}", cid):
        return no("which one?")
    async with db_pool.acquire() as conn:
        c = await conn.fetchrow("SELECT id, name, kind, size, grp, audience FROM usenet_cards WHERE id = $1", cid)
        if not c or CSAM_RX.search(c["name"]) or usenet_rules.forbidden({"name": c["name"], "groups": [c["grp"]], "audience": c["audience"]}):
            return no("no such item", 404)
        if c["kind"] not in _UN_GRAB_KINDS:
            return no("tgarr fetches only books, songs and pictures itself - video goes to Sonarr or Radarr")
        if c["audience"] == "nsfw" and not await _is_nsfw_enabled():
            return no("no such item", 404)
        if (c["size"] or 0) > usenet_fetch.MOST_ALL:
            return no("too large to fetch here")
        had = await conn.fetchrow("SELECT id, state FROM usenet_grabs WHERE card_id = $1 AND state IN ('queued', 'working', 'done') ORDER BY id DESC LIMIT 1", cid)
        if had:
            return {"status": "ok", "job": had["id"], "state": had["state"]}
    cfg = await _usenet_cfg()
    if not (cfg.get("enabled") and cfg.get("host")) or _USENET.get("ok") is False:     # asked here only what is already known:
        return no("Usenet is switched off or the news server is not answering", 503)   # the fetch itself finds out the rest
    async with db_pool.acquire() as conn:
        job = await conn.fetchval("INSERT INTO usenet_grabs (card_id, name, kind) VALUES ($1, $2, $3) RETURNING id", cid, c["name"], c["kind"])
    return {"status": "ok", "job": job, "state": "queued"}


@app.get("/api/usenet/grabs")
async def api_usenet_grabs():
    async with db_pool.acquire() as conn:
        rows = await conn.fetch(
            "SELECT id, card_id, name, kind, state, note, files, bytes, msg_id FROM usenet_grabs ORDER BY id DESC LIMIT 60")
    out = []
    for r in rows:
        d = dict(r)
        if d["state"] == "working" and _UN_GRAB["now"] == d["id"] and _UN_GRAB["of"]:
            d["percent"] = min(99, int(_UN_GRAB["bytes"] * 100 / _UN_GRAB["of"]))
        out.append(d)
    return {"grabs": out}


@app.get("/usenet", response_class=HTMLResponse)
async def page_usenet(q: Optional[str] = None, kind: str = ""):
    cfg = await _usenet_cfg()
    if not (cfg.get("enabled") and cfg.get("host")):
        body = (_KIDS_CSS + '<div class="km-box"><div class="km-pad"><h3 style="margin:0 0 6px">' + _t("Usenet is not set up") + '</h3>'
                '<p style="color:var(--muted);margin:0 0 12px">'
                + _t("With a Usenet account tgarr reads the newsgroups as well: films and series for Sonarr and Radarr, and books, songs and pictures it can fetch itself, straight into the Library, Music and the Gallery.")
                + '</p><a class="btn" href="/settings/usenet">' + _t("Set up") + '</a></div></div>')
        return HTMLResponse(_layout("Usenet", "/usenet", body, page_title="Usenet", top_actions_html=""))
    if kind == "have":
        return await _usenet_have_page()
    kind = kind if kind in [s[0] for s in _UN_SHELVES] else ""
    q = (q or "").strip()
    if q:
        await _usenet_from_registry(q)
    where = ["c.alive >= 0.5", "c.kind = ANY($1::text[])", "COALESCE(c.size, 0) <= $2"]
    params = [list(_UN_GRAB_KINDS), usenet_fetch.MOST_ALL]
    _aud0 = await _aud_default()                   # all-ages only, everything, or adult only: as the settings say
    if _aud0 == "sfw":
        where.append("c.audience <> 'nsfw'")
    elif _aud0 == "nsfw":
        where.append("c.audience = 'nsfw'")
    counted = " AND ".join(where)                  # the numbers on the shelves: before the search and the shelf
    if kind:
        params.append(kind)
        where.append(f"({_UN_SHELF_SQL}) = ${len(params)}")
    for w in re.split(r"[\s.]+", q)[:8]:
        if w:
            params.append("%" + w.replace("%", "").replace("_", r"\_") + "%")
            where.append(f"c.name ILIKE ${len(params)}")
    async with db_pool.acquire() as conn:
        rows = await conn.fetch(
            f"""SELECT c.id, c.name, c.kind, c.size, c.grp, c.posted_from, c.files, c.audience, c.sketch, ({_UN_SHELF_SQL}) AS shelf
                FROM usenet_cards c WHERE {' AND '.join(where)}
                ORDER BY c.posted_from DESC NULLS LAST LIMIT 150""", *params)
        counts = dict(await conn.fetch(
            f"SELECT ({_UN_SHELF_SQL}), count(*) FROM usenet_cards c WHERE {counted} GROUP BY 1", list(_UN_GRAB_KINDS), usenet_fetch.MOST_ALL))
        have_bytes = await conn.fetchval(
            f"""SELECT COALESCE(sum(m.file_size), 0) FROM messages m JOIN channels c ON c.id = m.channel_id
                WHERE {_FROM_USENET} AND m.local_path IS NOT NULL AND left(m.local_path, 2) <> '__'""")
    ico = {s[0]: s[1] for s in _UN_SHELVES}
    qs = f"&q={_q(q)}" if q else ""
    chips = "".join(
        f'<a class="btn ghost km-chip{" on" if k == kind else ""}" href="/usenet?kind={k}{qs}">{lbl} <span style="opacity:.6">{n:,}</span></a>'
        for k, lbl, n in [("", _t("All"), sum(counts.values()))] + [(s[0], f"{s[1]} {_t(s[2])}", counts.get(s[0], 0)) for s in _UN_SHELVES])
    chips += ('<a class="btn ghost km-chip" href="/usenet?kind=have" style="margin-left:auto" '
              f'title="{_t("what you fetched, and the room it takes")}">📥 {_t("Fetched")} <span style="opacity:.6">{_fmt_size(have_bytes) or "0"}</span></a>')
    items = "".join(
        f'<div class="km-row"><span class="n">{ico.get(r["shelf"], "")} {html.escape(r["name"])}'
        + (' <small>· 18+</small>' if r["audience"] == "nsfw" else "")
        # a card from a sparse reading saw only some of a release: one file is measured,
        # several are an estimate, and the count is of those seen
        + '<br/><small>' + (_t("about {size}", size=_fmt_size(r["size"]) or "?") if r["sketch"] and (r["files"] or 0) > 1 else (_fmt_size(r["size"]) or "?"))
        + (' · ' + _t("{n} files", n=f'{r["files"]}{"+" if r["sketch"] else ""}') if (r["files"] or 0) > 1 else "")
        + f' · {html.escape(r["grp"])} · {time.strftime("%Y-%m-%d", time.gmtime(r["posted_from"] or 0))}</small></span>'
        f'<span id="ug-{r["id"]}" style="white-space:nowrap"><button class="btn" onclick="ugGet(&quot;{r["id"]}&quot;,this)">{_t("Get")}</button></span></div>'
        for r in rows)
    body = (
        _KIDS_CSS
        + '<p style="color:var(--muted);margin:0 0 14px">'
        + _t("Books, songs and pictures found in the newsgroups. %1 fetches one through your Usenet account and puts it in the Library, Music or the Gallery. Only what was posted whole and can be opened as it is: nothing packed, never a program, never video - films and series go to Sonarr and Radarr.").replace("%1", "<b>" + _t("Get") + "</b>")
        + '</p>'
        + f'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">{chips}</div>'
        + (f'<div class="km-box">{items}</div>' if items else
           '<div class="km-box"><div class="km-pad" style="color:var(--muted)">'
           + (_t("Nothing found for these words.") if q else _t("Nothing yet. Cards appear here as the newsgroups are read; searching also asks the shared index."))
           + '</div></div>')
        + _grab_note_js() + _fill("""<script>
const ugEsc = t => String(t || "").replace(/[&<>]/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;"})[c]);
function ugShow(g){
  const e = document.getElementById("ug-" + g.card_id);
  if (!e) return false;
  const again = '<button class="btn ghost" onclick="ugGet(&quot;' + g.card_id + '&quot;,this)">' + "[[@js:Try again]]" + '</button>';
  const open = g.msg_id ? '<a class="btn ghost" href="/watch/' + g.msg_id + '">' + "[[@js:Open]]" + '</a>' : "";
  if (g.state === "queued") e.innerHTML = '<small>' + "[[@js:waiting]]" + '</small>';
  else if (g.state === "working") e.innerHTML = '<small>' + (g.percent != null ? "[[@js:fetching %1%]]".replace("%1", g.percent) : "[[@js:fetching]]") + '</small>';
  else if (g.state === "done") e.innerHTML = '<small>' + "[[@js:fetched]]" + '</small> ' + open;
  else if (g.state === "partial") e.innerHTML = '<small>' + ugEsc(grabNote(g.note)) + '</small> ' + open;
  // "try again" only where trying again can help: not for what is refused for what it is
  else e.innerHTML = '<small style="color:#b45309">' + ugEsc(grabNote(g.note) || "[[@js:that did not work]]") + '</small> '
    + (!g.note || /try again|room left/.test(g.note) ? again : "");
  return g.state === "queued" || g.state === "working";
}
function ugPoll(){
  fetch("/api/usenet/grabs").then(r => r.json()).then(j => {
    const seen = new Set(); let busy = false;
    (j.grabs || []).forEach(g => { if (seen.has(g.card_id)) return; seen.add(g.card_id); if (ugShow(g)) busy = true; });
    if (busy) setTimeout(ugPoll, 2500);
  }).catch(() => setTimeout(ugPoll, 8000));
}
function ugGet(id, b){
  b.disabled = true;
  fetch("/api/usenet/grab", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({id: id})})
    .then(r => r.json()).then(j => { if (j.status === "ok") ugPoll(); else { b.disabled = false; alert(j.message || "[[@js:that did not work]]"); } })
    .catch(() => { b.disabled = false; });
}
ugPoll();
</script>"""))
    top = ('<form action="/usenet" method="GET" style="margin-left:auto">'
           + (f'<input type="hidden" name="kind" value="{kind}"/>' if kind else "")
           + f'<input type="text" name="q" class="search" placeholder="{_t("Search books, songs, pictures on Usenet…")}" value="{html.escape(q, quote=True)}"/></form>')
    return HTMLResponse(_layout("Usenet", "/usenet", body, page_title="Usenet", top_actions_html=top))


# ════════════════════════════════════════════════════════════════════
# The Internet Archive (archive_org.py)
#
# A third source beside Telegram and Usenet, and the one that needs nothing: no account, no
# provider. Nothing of it is indexed here - the page asks archive.org when somebody searches -
# and Get fetches an item over HTTPS into /downloads/archive/<shelf>/, where it is a file of
# this install like any other: it plays in Videos, Music, the Library, the Gallery, the Media
# Center. Fetched by hand, so removed by hand (the cache rules leave it alone).
# ════════════════════════════════════════════════════════════════════
ARCHIVE_ROOT = "archive"
_AR_GRAB = {"now": None, "bytes": 0, "of": 0}
_AR_CACHE = {}                           # (words, shelf, page) -> (when, how many in all, items)


def _archive_ok(*names) -> bool:
    """Not something the guard refuses by its name."""
    return not (any(CSAM_RX.search(x or "") for x in names) or usenet_rules.never_kept(list(names), [], False))


async def _archive_search(q: str, shelf: str, page: int) -> tuple:
    key = (archive_org.clean_query(q), shelf, page)
    hit = _AR_CACHE.get(key)
    if hit and time.time() - hit[0] < 600:
        return hit[1], hit[2], ""
    try:
        body = await asyncio.to_thread(archive_org.fetch_json, archive_org.search_url(q, shelf, page))
    except Exception as e:
        log.info("[archive] search: %s: %s", type(e).__name__, str(e)[:120])
        return 0, [], "archive.org did not answer - try again in a moment"
    total, items = archive_org.parse_search(body)
    items = [i for i in items if _archive_ok(i["title"], i["id"], i["creator"])]
    if len(_AR_CACHE) > 300:
        _AR_CACHE.clear()
    _AR_CACHE[key] = (time.time(), total, items)
    return total, items, ""


def _archive_fetch_files(ident: str, take: list, folder: str, single_name: str, progress) -> list:
    """In a thread: the files, one after another. [(path, size, title)] of those that arrived whole."""
    done, names = [], set()
    for f in take:
        base = single_name if (single_name and len(take) == 1) else os.path.basename(f["name"])
        name = localfiles.free_name(lambda x: x in names or os.path.exists(os.path.join(folder, x)), localfiles.safe_name(base))
        names.add(name)
        for attempt in (1, 2):
            try:
                size = archive_org.download(archive_org.file_url(ident, f["name"]), os.path.join(folder, name), progress, f["size"])
                done.append((os.path.join(folder, name), size, f.get("title") or ""))
                break
            except Exception as e:
                log.info("[archive] %s / %s (try %d): %s: %s", ident, f["name"][:80], attempt, type(e).__name__, str(e)[:120])
    return done


async def _archive_grab_one(job) -> tuple:
    """(state, note, files, bytes, message id of the first file)."""
    import shutil
    ident = job["item_id"]
    meta = None
    for attempt in (1, 2, 3):                       # the Archive is slow now and then: one silence is not a no
        try:
            meta = await asyncio.to_thread(archive_org.fetch_json, archive_org.metadata_url(ident), 40)
            break
        except Exception as e:
            log.info("[archive] %s: asking what it holds (try %d): %s: %s", ident, attempt, type(e).__name__, str(e)[:120])
            if attempt < 3:
                await asyncio.sleep(5 * attempt)
    if meta is None:
        return "failed", "archive.org did not answer (asked three times) - try again later", 0, 0, None
    p = archive_org.plan(meta)
    if not p["take"]:
        return "failed", p["why"], 0, 0, None
    if not _archive_ok(p["title"], ident, *[f["name"] for f in p["take"]]):
        await _usenet_blocked("archive item", "a term for it in its name", p["title"])
        return "failed", "never fetched: the block list", 0, 0, None
    if p["bytes"] > shutil.disk_usage("/downloads").free - (1 << 30):
        return "failed", "not enough room left on the disk", 0, 0, None
    label = (localfiles.safe_name(p["title"])[:110].strip(" .") or ident) + (f" ({p['year']})" if p["year"] else "")
    base = f"/downloads/{ARCHIVE_ROOT}/{archive_org.SHELF[p['shelf']][4]}"
    single = ""
    if len(p["take"]) == 1:
        single = f"{label}.{archive_org.ext(p['take'][0]['name'])}"
    else:
        base = os.path.join(base, localfiles.free_name(lambda x: os.path.exists(os.path.join(base, x)), label))
    os.makedirs(base, exist_ok=True)
    _AR_GRAB.update(now=job["id"], bytes=0, of=p["bytes"])

    def progress(n):
        _AR_GRAB["bytes"] += n
    try:
        done = await asyncio.to_thread(_archive_fetch_files, ident, p["take"], base, single, progress)
    finally:
        _AR_GRAB["now"] = None
    if not done:
        if not single:
            try:
                os.rmdir(base)
            except OSError:
                pass
        return "failed", "it did not arrive from archive.org - try again later", 0, 0, None
    now = int(time.time())
    rels = [(os.path.relpath(path, "/downloads").replace(os.sep, "/"), size, now) for path, size, _t in sorted(done)]
    caption = f"{p['title']} · archive.org/details/{ident}" + (f" · {p['year']}" if p["year"] else "")
    async with db_pool.acquire() as conn:
        await _local_add(conn, ARCHIVE_ROOT, rels)
        await conn.execute("UPDATE messages SET caption = $2 WHERE local_path = ANY($1::text[])", [r[0] for r in rels], caption)
        if p["shelf"] in ("audio", "audiobook"):           # a chapter's or a song's own title, and what it belongs to
            for path, _size, title in done:
                await conn.execute("UPDATE messages SET audio_title = COALESCE(NULLIF($2, ''), audio_title), audio_album = $3 WHERE local_path = $1",
                                   os.path.relpath(path, "/downloads").replace(os.sep, "/"), title, p["title"][:200])
        mid = await conn.fetchval("SELECT id FROM messages WHERE local_path = $1 ORDER BY id DESC LIMIT 1", rels[0][0])
    whole = len(done) == len(p["take"])
    note = "" if whole else f"{len(done)} of {len(p['take'])} files arrived whole"
    if p["why"]:
        note = (note + "; " if note else "") + p["why"]
    return ("done" if whole and not p["why"] else "partial", note, len(done), sum(sz for _p, sz, _t in done), mid)


async def _archive_grab_worker():
    await asyncio.sleep(45)
    try:
        async with db_pool.acquire() as conn:      # what a restart interrupted starts over
            await conn.execute("UPDATE archive_grabs SET state = 'queued' WHERE state = 'working'")
    except Exception:
        log.exception("[archive] could not tidy up after a restart")
    while True:
        try:
            async with db_pool.acquire() as conn:
                job = await conn.fetchrow(
                    """UPDATE archive_grabs SET state = 'working' WHERE id =
                       (SELECT id FROM archive_grabs WHERE state = 'queued' ORDER BY id LIMIT 1) RETURNING *""")
            if not job:
                await asyncio.sleep(3)
                continue
            try:
                res = await _archive_grab_one(job)
            except Exception as e:
                log.warning("[archive] fetching %s: %s: %s", job["item_id"], type(e).__name__, str(e)[:160])
                res = ("failed", "that did not work - try again later", 0, 0, None)
            async with db_pool.acquire() as conn:
                await conn.execute(
                    "UPDATE archive_grabs SET state = $2, note = $3, files = $4, bytes = $5, msg_id = $6, done_at = NOW() WHERE id = $1",
                    job["id"], *res)
            log.info("[archive] fetched %s (%s): %s%s, %s file(s), %s", job["item_id"], job["name"][:60], res[0],
                     f" - {res[1]}" if res[1] else "", res[2], _fmt_size(res[3]) or "0")
        except Exception as e:
            log.warning("[archive] the fetching: %s: %s", type(e).__name__, str(e)[:160])
            await asyncio.sleep(20)


# ───────────────────────── the Internet Archive, for Radarr ─────────────────────────
# Radarr asks tgarr's indexer for a film; beside what Telegram holds, the Archive is asked,
# and what it has under that title is offered as a release ("Title.Year.480p.WEB-archive.org").
# Grabbed, it is fetched over HTTPS by the worker below into the folder Radarr collects from,
# and reported through the same download-client answers as a Telegram download. None of it
# needs an account of any kind. Films only: a series at the Archive is one item of many files
# with no season and episode in their names, and Sonarr could not tell them apart.
# Switch: config key newznab_archive = 'false'.
_AR_META = {}                            # item -> (when, what the Archive says of it)


async def _archive_meta(ident: str):
    hit = _AR_META.get(ident)
    if hit and time.time() - hit[0] < 3600:
        return hit[1]
    try:
        meta = await asyncio.to_thread(archive_org.fetch_json, archive_org.metadata_url(ident), 20)
    except Exception:
        return None
    if len(_AR_META) > 500:
        _AR_META.clear()
    _AR_META[ident] = (time.time(), meta)
    return meta


async def _archive_for_arr(q: str) -> list:
    """What the Archive has of a film Radarr asks for: [{guid, name, size, year, item_id, file}],
    at most six, each remembered so that a grab finds it."""
    import uuid
    async with db_pool.acquire() as conn:
        if ((await conn.fetchval("SELECT value FROM config WHERE key = 'newznab_archive'")) or "").lower() == "false":
            return []
    asked, asked_year = archive_org.split_year(q)
    if len(asked) < 2:
        return []
    # tgarr.me first: it keeps a list of the Archive's items people download, and answering
    # from it spares the Archive a search for every film on every install's list. Its answer
    # is taken as it is, also when it knows of none; only when it does not answer at all is
    # the Archive itself asked.
    try:
        body = await asyncio.wait_for(asyncio.to_thread(
            archive_org.fetch_json, archive_org.registry_url(UPDATE_REGISTRY_URL, asked, asked_year), 8), 10)
        found = archive_org.parse_registry(body)
    except Exception:
        _total, found, _trouble = await _archive_search(asked, "film", 1)
    picked = [i for i in found if archive_org.is_the_film(i["title"], i["year"], asked, asked_year) and not re.search(ADULT_RX, i["title"], re.I)][:6]
    out = []
    for i, meta in zip(picked, await asyncio.gather(*[_archive_meta(i["id"]) for i in picked])):
        if not meta:
            continue
        p = archive_org.plan(meta)
        f = archive_org.film_file(p)
        if not f or not _archive_ok(p["title"], i["id"], f["name"]):
            continue
        year = p["year"] or i["year"]
        if asked_year and year != asked_year:      # asked with a year: an item that names none is not offered
            continue                               # (it could be the other film of that title)
        out.append({"guid": str(uuid.uuid5(uuid.NAMESPACE_URL, "https://archive.org/details/" + i["id"])),
                    "name": archive_org.release_name(p["title"], year, f["height"]), "size": f["size"], "year": year,
                    "item_id": i["id"], "file": f["name"]})
    if out:
        async with db_pool.acquire() as conn:
            await conn.executemany(
                """INSERT INTO archive_items (guid, item_id, file, name, size, year) VALUES ($1::uuid, $2, $3, $4, $5, $6)
                   ON CONFLICT (guid) DO UPDATE SET file = EXCLUDED.file, name = EXCLUDED.name, size = EXCLUDED.size, seen_at = NOW()""",
                [(o["guid"], o["item_id"], o["file"], o["name"], o["size"], o["year"]) for o in out])
    return out


def _archive_item_xml(o: dict, base_url: str, apikey: str) -> str:
    import calendar
    link = html.escape(f"{base_url}/newznab/api?t=get&id={o['guid']}&apikey={apikey}", quote=True)
    year = int(o["year"]) if (o["year"] or "").isdigit() else 1970
    pub = time.strftime("%a, %d %b %Y %H:%M:%S +0000", time.gmtime(max(0, calendar.timegm((max(year, 1970), 1, 1, 0, 0, 0)))))
    return (
        f"    <item>\n"
        f"      <title>{html.escape(o['name'])}</title>\n"
        f"      <guid isPermaLink=\"false\">{o['guid']}</guid>\n"
        f"      <link>{link}</link>\n"
        f"      <comments>{html.escape('https://archive.org/details/' + o['item_id'], quote=True)}</comments>\n"
        f"      <pubDate>{pub}</pubDate>\n"
        f"      <category>2000</category>\n"
        f"      <size>{o['size']}</size>\n"
        f"      <description>from the Internet Archive, fetched by tgarr over HTTPS</description>\n"
        f"      <enclosure url=\"{link}\" length=\"{o['size']}\" type=\"application/x-nzb\"/>\n"
        f"      <newznab:attr name=\"category\" value=\"2000\"/>\n"
        f"      <newznab:attr name=\"size\" value=\"{o['size']}\"/>\n"
        f"      <newznab:attr name=\"guid\" value=\"{o['guid']}\"/>\n"
        f"    </item>")


async def _archive_release(conn, guid: str):
    """The release row of an Archive film that was offered and is now grabbed (made at this
    moment: what is only offered is not a release of this install). None: not one of them."""
    it = await conn.fetchrow("SELECT * FROM archive_items WHERE guid = $1::uuid", guid)
    if not it:
        return None
    rid = await conn.fetchval(
        """INSERT INTO releases (guid, name, category, movie_title, movie_year, source, size_bytes, posted_at)
           VALUES ($1::uuid, $2, 'movie', $3, $4, 'archive.org', $5, NOW())
           ON CONFLICT (guid) DO UPDATE SET name = EXCLUDED.name, size_bytes = EXCLUDED.size_bytes RETURNING id""",
        guid, it["name"], it["name"].split(".WEB-archive.org")[0], int(it["year"]) if (it["year"] or "").isdigit() else None, it["size"])
    return {"id": rid, "name": it["name"]}


async def _archive_arr_one(d) -> None:
    import shutil
    folder = os.path.join("/downloads/tgarr", localfiles.safe_name(d["name"])[:150])
    dest = os.path.join(folder, localfiles.safe_name(f"{d['name']}.{archive_org.ext(d['file']) or 'mp4'}"))
    if (d["size"] or 0) > shutil.disk_usage("/downloads").free - (1 << 30):
        raise OSError("not enough room left on the disk")
    os.makedirs(folder, exist_ok=True)
    seen = {"n": 0, "at": time.time(), "last": 0}

    async def pump():
        while True:
            await asyncio.sleep(3)
            now = time.time()
            kbps = int((seen["n"] - seen["last"]) / 1024 / max(0.5, now - seen["at"]))
            seen.update(at=now, last=seen["n"])
            async with db_pool.acquire() as conn:
                await conn.execute(
                    "UPDATE downloads SET bytes_done = $2, speed_kbps = $3, last_progress_at = NOW() WHERE id = $1 AND status = 'downloading'",
                    d["dl_id"], seen["n"], kbps)

    def progress(n):
        seen["n"] += n
    pumping = asyncio.create_task(pump())
    try:
        size = await asyncio.to_thread(archive_org.download, archive_org.file_url(d["item_id"], d["file"]), dest, progress)
    finally:
        pumping.cancel()
    try:
        os.chmod(folder, 0o777)
        os.chmod(dest, 0o666)
    except OSError:
        pass
    async with db_pool.acquire() as conn:
        await conn.execute(
            "UPDATE downloads SET status = 'completed', finished_at = NOW(), local_path = $2, bytes_done = $3, speed_kbps = 0 WHERE id = $1 AND status <> 'cancelled'",
            d["dl_id"], dest, size)
        await conn.execute("UPDATE releases SET size_bytes = $2 WHERE id = $1", d["release_id"], size)
    log.info("[archive] for Radarr: %s arrived, %s", d["name"][:80], _fmt_size(size) or "0")


async def _archive_arr_worker():
    """Downloads of Archive films that Radarr (or the Releases page) asked for. The crawler's
    own worker never takes these: it claims what has a Telegram message behind it."""
    await asyncio.sleep(50)
    mine = "release_id IN (SELECT r.id FROM releases r JOIN archive_items a ON a.guid = r.guid)"
    try:
        async with db_pool.acquire() as conn:      # what a restart interrupted starts over
            await conn.execute(f"UPDATE downloads SET status = 'pending' WHERE status = 'downloading' AND {mine}")
    except Exception:
        log.exception("[archive] could not tidy up after a restart")
    while True:
        try:
            async with db_pool.acquire() as conn:
                d = await conn.fetchrow(
                    f"""WITH claim AS (SELECT id FROM downloads WHERE status = 'pending' AND {mine}
                                       ORDER BY requested_at LIMIT 1 FOR UPDATE SKIP LOCKED)
                        UPDATE downloads SET status = 'downloading' WHERE id IN (SELECT id FROM claim) RETURNING id AS dl_id, release_id""")
                if d:
                    d = await conn.fetchrow(
                        """SELECT $1::bigint AS dl_id, r.id AS release_id, r.name, a.item_id, a.file, a.size
                           FROM releases r JOIN archive_items a ON a.guid = r.guid WHERE r.id = $2""", d["dl_id"], d["release_id"])
            if not d:
                await asyncio.sleep(4)
                continue
            try:
                await _archive_arr_one(d)
            except Exception as e:
                log.warning("[archive] for Radarr: %s: %s: %s", d["name"][:80], type(e).__name__, str(e)[:160])
                async with db_pool.acquire() as conn:
                    await conn.execute(
                        "UPDATE downloads SET status = 'failed', finished_at = NOW(), error_message = $2 WHERE id = $1 AND status = 'downloading'",
                        d["dl_id"], f"archive.org: {str(e)[:200]}")
        except Exception as e:
            log.warning("[archive] the Radarr fetching: %s: %s", type(e).__name__, str(e)[:160])
            await asyncio.sleep(20)


@app.post("/api/archive/grab")
async def api_archive_grab(request: Request):
    def no(msg, code=400):
        return JSONResponse({"status": "error", "message": msg}, status_code=code)
    try:
        b = await request.json()
        ident, name, shelf = str(b.get("id") or ""), str(b.get("name") or "")[:300], str(b.get("shelf") or "")
    except Exception:
        ident, name, shelf = "", "", ""
    if not archive_org.ID_RX.fullmatch(ident):
        return no("which one?")
    if not _archive_ok(name, ident):
        return no("no such item", 404)
    async with db_pool.acquire() as conn:
        had = await conn.fetchrow("SELECT id, state FROM archive_grabs WHERE item_id = $1 AND state IN ('queued', 'working', 'done') ORDER BY id DESC LIMIT 1", ident)
        if had:
            return {"status": "ok", "job": had["id"], "state": had["state"]}
        if await conn.fetchval("SELECT count(*) FROM archive_grabs WHERE state IN ('queued', 'working')") >= 50:
            return no("fifty are waiting already - let some arrive first", 429)
        job = await conn.fetchval("INSERT INTO archive_grabs (item_id, name, kind) VALUES ($1, $2, $3) RETURNING id",
                                  ident, name or ident, shelf if shelf in archive_org.SHELF else None)
    return {"status": "ok", "job": job, "state": "queued"}


@app.get("/api/archive/grabs")
async def api_archive_grabs():
    async with db_pool.acquire() as conn:
        rows = await conn.fetch("SELECT id, item_id, name, kind, state, note, files, bytes, msg_id FROM archive_grabs ORDER BY id DESC LIMIT 60")
    out = []
    for r in rows:
        d = dict(r)
        if d["state"] == "working" and _AR_GRAB["now"] == d["id"] and _AR_GRAB["of"]:
            d["percent"] = min(99, int(_AR_GRAB["bytes"] * 100 / _AR_GRAB["of"]))
        out.append(d)
    return {"grabs": out}


@app.post("/api/archive/forget")
async def api_archive_forget(request: Request):
    """Remove what was fetched: {"release": key} one item, {"all": true} everything."""
    try:
        b = await request.json()
    except Exception:
        b = {}
    cond, params = None, []
    if b.get("all") is True:
        cond = "TRUE"
    elif isinstance(b.get("release"), str) and re.fullmatch(r"[0-9a-f]{32}", b["release"]):
        cond, params = "md5(COALESCE(m.caption, m.local_path)) = $1", [b["release"]]
    if not cond:
        return JSONResponse({"status": "error", "message": "what to remove?"}, status_code=400)
    async with db_pool.acquire() as conn:
        rows = await conn.fetch(
            f"""SELECT m.local_path, COALESCE(m.file_size, 0) AS sz, m.caption FROM messages m JOIN channels c ON c.id = m.channel_id
                WHERE c.local_root = '{ARCHIVE_ROOT}' AND m.local_path IS NOT NULL AND left(m.local_path, 2) <> '__' AND {cond}""", *params)
        paths = [r["local_path"] for r in rows if r["local_path"].startswith(ARCHIVE_ROOT + "/")]
        if paths:                                  # so that Get offers it again
            idents = {m.group(1) for m in (re.search(r"archive\.org/details/([A-Za-z0-9._-]+)", r["caption"] or "") for r in rows) if m}
            await conn.execute("DELETE FROM archive_grabs WHERE item_id = ANY($1::text[])", list(idents))
    if paths:
        await _fetched_forget(paths)
        log.info("[archive] removed by hand: %d file(s), %s", len(paths), _fmt_size(sum(r["sz"] for r in rows)) or "0")
    return {"status": "ok", "removed": len(paths), "freed": _fmt_size(sum(r["sz"] for r in rows)) or "0 MB"}


_AR_JS = """<script>
const agEsc = t => String(t || "").replace(/[&<>]/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;"})[c]);
function agShow(g){
  const e = document.querySelector('[data-ag="' + CSS.escape(g.item_id) + '"]');
  if (!e) return false;
  const open = g.msg_id ? '<a class="btn ghost" href="/watch/' + g.msg_id + '">' + "[[@js:Open]]" + '</a>' : "";
  if (g.state === "queued") e.innerHTML = '<small>' + "[[@js:waiting]]" + '</small>';
  else if (g.state === "working") e.innerHTML = '<small>' + (g.percent != null ? "[[@js:fetching %1%]]".replace("%1", g.percent) : "[[@js:fetching]]") + '</small>';
  else if (g.state === "done") e.innerHTML = '<small>' + "[[@js:fetched]]" + '</small> ' + open;
  else if (g.state === "partial") e.innerHTML = '<small>' + agEsc(grabNote(g.note)) + '</small> ' + open;
  else e.innerHTML = '<small style="color:#b45309">' + agEsc(grabNote(g.note) || "[[@js:that did not work]]") + '</small> '
    + (!g.note || /try again|room left/.test(g.note) ? '<button class="btn ghost" data-again="1">' + "[[@js:Try again]]" + '</button>' : "");
  const again = e.querySelector("[data-again]");
  if (again) again.onclick = () => agGet(e, again);
  return g.state === "queued" || g.state === "working";
}
function agPoll(){
  fetch("/api/archive/grabs").then(r => r.json()).then(j => {
    const seen = new Set(); let busy = false;
    (j.grabs || []).forEach(g => { if (seen.has(g.item_id)) return; seen.add(g.item_id); if (agShow(g)) busy = true; });
    if (busy) setTimeout(agPoll, 2500);
  }).catch(() => setTimeout(agPoll, 8000));
}
function agGet(e, b){
  b.disabled = true;
  fetch("/api/archive/grab", {method: "POST", headers: {"Content-Type": "application/json"},
                              body: JSON.stringify({id: e.dataset.ag, name: e.dataset.name, shelf: e.dataset.shelf})})
    .then(r => r.json()).then(j => { if (j.status === "ok") agPoll(); else { b.disabled = false; alert(j.message || "[[@js:that did not work]]"); } })
    .catch(() => { b.disabled = false; });
}
function agForget(body, what, b){
  if (!confirm(what)) return;
  if (b) b.disabled = true;
  fetch("/api/archive/forget", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(body)})
    .then(r => r.json()).then(j => { if (j.status === "ok") location.reload(); else { if (b) b.disabled = false; alert(j.message || "[[@js:that did not work]]"); } })
    .catch(() => { if (b) b.disabled = false; });
}
document.querySelectorAll("[data-ag] button").forEach(b => { b.onclick = () => agGet(b.parentElement, b); });
agPoll();
</script>"""


@app.get("/archive", response_class=HTMLResponse)
async def page_archive(q: Optional[str] = None, shelf: str = "film", page: int = 1, kind: str = ""):
    q = (q or "").strip()[:200]
    shelf = shelf if shelf in archive_org.SHELF else "film"
    page = max(1, min(int(page or 1), 250))
    async with db_pool.acquire() as conn:
        have = await conn.fetch(
            f"""SELECT md5(COALESCE(m.caption, m.local_path)) AS key, max(m.caption) AS cap, count(*) AS files,
                       sum(COALESCE(m.file_size, 0)) AS bytes, min(m.id) AS first, max(m.posted_at) AS fetched
                FROM messages m JOIN channels c ON c.id = m.channel_id
                WHERE c.local_root = '{ARCHIVE_ROOT}' AND m.local_path IS NOT NULL AND left(m.local_path, 2) <> '__'
                GROUP BY 1 ORDER BY max(m.id) DESC LIMIT 500""")
    have_bytes = sum(r["bytes"] for r in have)

    from urllib.parse import quote as _q

    def link(**over):
        cur = {"q": q, "shelf": shelf if shelf != "film" else None, "page": None, "kind": None}
        cur.update(over)
        bits = [f"{k}={_q(str(v))}" for k, v in cur.items() if v not in (None, "", 0)]
        return "/archive" + ("?" + "&".join(bits) if bits else "")
    shelf_word = {"film": _t("Films"), "audiobook": _t("Audiobooks"), "audio": _t("Music and radio"),
                  "book": _t("Books and magazines"), "picture": _t("Pictures")}
    chips = ("".join(_chip_link(f"{s[1]} {shelf_word.get(s[0], s[2])}", link(shelf=s[0] if s[0] != "film" else None), kind != "have" and shelf == s[0])
                     for s in archive_org.SHELVES)
             + (_chip_link(("📥 " + _t("Fetched") + f" {_fmt_size(have_bytes) or ''}").strip(), link(kind="have", q=None, shelf=None), kind == "have",
                           html.unescape(_t("what you fetched from the Internet Archive, and the way to remove it"))) if have else ""))
    if kind == "have":
        ar_one = html.escape(_tj("Remove this item from this server? The files are deleted; they can be fetched again from the Internet Archive."), quote=True)
        ar_all = html.escape(_tj("Remove everything fetched from the Internet Archive from this server? The files are deleted; they can be fetched again from the Internet Archive."), quote=True)
        items = "".join(
            f'<div class="km-row"><span class="n">{html.escape((r["cap"] or "").split(" · ")[0])}'
            f'<br/><small>{_fmt_size(r["bytes"]) or "0"} · {_t("files: {n}", n=r["files"])} · {_t("fetched %1").replace("%1", _ago(r["fetched"]))}</small></span>'
            '<span style="white-space:nowrap">'
            f'<a class="btn ghost" href="/watch/{r["first"]}">{_t("Open")}</a> '
            f'<button class="btn ghost" onclick="agForget({{release:&quot;{r["key"]}&quot;}},&quot;{ar_one}&quot;,this)">{_t("Delete")}</button></span></div>'
            for r in have)
        body = (_KIDS_CSS
                + '<p style="color:var(--muted);margin:0 0 14px">'
                + _t("Items fetched from the Internet Archive: %1, taking %2. You asked for each of these, so tgarr never removes one by itself.")
                  .replace("%1", f"<b>{len(have):,}</b>").replace("%2", f'<b>{_fmt_size(have_bytes) or "0 MB"}</b>') + '</p>'
                + f'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">{chips}'
                + ('<button class="btn ghost" style="margin-left:auto" onclick="agForget({all:true},&quot;' + ar_all + '&quot;,this)">'
                   f'🗑 {_t("Delete all ({size})", size=_fmt_size(have_bytes) or "0")}</button>' if have else "")
                + '</div>'
                + (f'<div class="km-box">{items}</div>' if items else '<div class="km-box"><div class="km-pad" style="color:var(--muted)">' + _t("Nothing fetched yet.") + '</div></div>')
                + _grab_note_js() + _fill(_AR_JS))
        return HTMLResponse(_layout("Archive", "/archive", body, page_title="Fetched from the Internet Archive", top_actions_html=""))
    total, found, trouble = await _archive_search(q, shelf, page)
    sign = archive_org.SHELF[shelf][1]
    items = "".join(
        f'<div class="km-row"><span class="n">{sign} {html.escape(i["title"])}'
        + (f' <small>({html.escape(i["year"])})</small>' if i["year"] else "")
        + '<br/><small>'
        + " · ".join(x for x in ((html.escape(i["creator"]) if i["creator"] else ""),
                                 (_t("up to {size}", size=_fmt_size(i["size"])) if i["size"] else ""),
                                 _t("{n} downloads", n=format(i["downloads"], ",")),
                                 f'<a href="https://archive.org/details/{html.escape(i["id"], quote=True)}" target="_blank" rel="noopener noreferrer">archive.org ↗</a>') if x)
        + '</small></span>'
        f'<span data-ag="{html.escape(i["id"], quote=True)}" data-name="{html.escape(i["title"], quote=True)}" data-shelf="{shelf}" style="white-space:nowrap">'
        '<button class="btn">' + _t("Get") + '</button></span></div>'
        for i in found)
    pages = ""
    if total > archive_org.ROWS or page > 1:
        last = min(250, (total + archive_org.ROWS - 1) // archive_org.ROWS)
        pages = ('<div style="display:flex;gap:8px;align-items:center;margin-top:14px">'
                 + (f'<a class="btn ghost" href="{html.escape(link(page=page - 1 if page > 2 else None), quote=True)}">← {_t("Earlier")}</a>' if page > 1 else "")
                 + f'<span style="color:var(--muted);font-size:13px">{_t("page {page} of {last} · {total} found", page=page, last=format(max(last, 1), ","), total=format(total, ","))}</span>'
                 + (f'<a class="btn ghost" href="{html.escape(link(page=page + 1), quote=True)}">{_t("More")} →</a>' if page < last else "")
                 + '</div>')
    body = (
        _KIDS_CSS
        + '<p style="color:var(--muted);margin:0 0 14px">'
        + _t("The %1 keeps films, radio plays, audiobooks, books, magazines and recordings that anybody may download - no account, no provider. %2 fetches an item to this server and puts it in Videos, Music or the Library: one playable copy of it, never a program. Without words, a shelf shows what is downloaded most.")
          .replace("%1", '<a href="https://archive.org" target="_blank" rel="noopener noreferrer">' + _t("Internet Archive") + '</a>').replace("%2", "<b>" + _t("Get") + "</b>")
        + '</p>'
        + f'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">{chips}</div>'
        + (f'<div class="km-box">{items}</div>' if items else
           '<div class="km-box"><div class="km-pad" style="color:var(--muted)">'
           + (_t(trouble) if trouble else _t("Nothing found for these words on this shelf.")) + '</div></div>')
        + pages + _grab_note_js() + _fill(_AR_JS))
    top = ('<form action="/archive" method="GET" style="margin-left:auto">'
           + (f'<input type="hidden" name="shelf" value="{shelf}"/>' if shelf != "film" else "")
           + f'<input type="text" name="q" class="search" placeholder="{_t("Search the Internet Archive…")}" value="{html.escape(q, quote=True)}"/></form>')
    return HTMLResponse(_layout("Archive", "/archive", body, page_title="Internet Archive", top_actions_html=top))


